  -- [13] Vending Machine Sugary Drinks Ban
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '5421fa67-b79f-4e9e-b509-6a7e87fda3ea',
    'Vending Machine Sugary Drinks Ban',
    'recognising_assumptions'::dm_question_type,
    'Should sugary drinks be banned from school vending machines to reduce the obesity rate among secondary school students?',
    NULL,
    NULL,
    'B',
    'B addresses both the action (banning sugary drinks) and the outcome (obesity rate) and grounds it in a controlled study with a measured effect size. A relies on an unsupported assumption about teenager preferences. C addresses calorie share at school but offers no evidence about whether this would change the obesity rate. D addresses funding for sports equipment, which is tangential to the obesity outcome.',
    13,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; teenagers find vending-machine drinks unappealing compared to bottled water, so removing sugary drinks will encourage them to make healthier choices.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; a five-year study of 200 secondary schools found that schools removing sugary drinks from vending machines saw a 6% drop in their student obesity rate compared with control schools.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; school vending machine sales make up only a small fraction of the total daily calorie intake of most students.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; vending machine revenue funds school sports equipment, which contributes to physical activity for students.', NULL, 4, NULL
  );

