  -- [15] Coloured Tokens
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '2cf31ed3-24a5-4f52-b15c-a423421b02cf',
    'Coloured Tokens',
    'probabilistic'::dm_question_type,
    'A bag contains 6 red tokens, 5 yellow tokens and 4 black tokens. Two tokens are drawn at random, one after the other, without replacement.

What is the probability that both tokens are yellow?',
    NULL,
    NULL,
    'A',
    'Total tokens = 15. P(first yellow) = 5/15 = 1/3. After one yellow is removed, 4 yellow remain in 14 tokens. P(second yellow given first yellow) = 4/14 = 2/7. P(both yellow) = (1/3) × (2/7) = 2/21.',
    15,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

