  -- [21] Drink Orders
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'bcc3988d-579e-409f-9539-85082093cb73',
    'Drink Orders',
    'venn_diagram'::dm_question_type,
    'A café logs 80 drink orders on a morning. 34 contain caffeine, 28 contain milk, 22 contain sugar. 12 contain both caffeine and milk, 8 contain both milk and sugar, 4 contain both caffeine and sugar. 2 drinks contain all three. 18 drinks contain none of these three.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'B',
    'Freebies: 2 contain all three and 18 contain none. Scan — A shows 4 in the centre, not 2 — eliminate A. C shows 20 outside, not 18 — eliminate C. That leaves B and D. The stem says 4 drinks contain caffeine and sugar; in D the caffeine-and-sugar total is 6 + 2 = 8 — eliminate D. B matches every stated figure. Answer: B.',
    21,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

