  -- [22] Five Swimmers Lanes
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'f418eeef-a1b3-434c-9eb7-d9cba901bab5',
    'Five Swimmers Lanes',
    'logic_puzzle'::dm_question_type,
    'Five swimmers — Priya, Quinn, Rafa, Sam and Tess — are assigned to lanes 1 to 5 (lane 1 is furthest left). Priya is immediately to the right of Rafa. Tess is in lane 5. Quinn is immediately to the left of Sam. Rafa is in lane 1.

Who is in lane 3?',
    NULL,
    NULL,
    'D',
    'Rafa is in lane 1 and Priya is immediately to the right, so Priya is in lane 2. Tess is in lane 5. Quinn and Sam must fill lanes 3 and 4, with Sam immediately to the right of Quinn, giving Quinn in lane 3 and Sam in lane 4.',
    22,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

