  -- [23] Team Pairing
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'a58c27cb-7fb0-4081-9592-5c7058dd0f00',
    'Team Pairing',
    'logic_puzzle'::dm_question_type,
    'A manager must pair four new hires (Priya, Quinn, Ravi, Sam) with four mentors (Wren, Xia, Yousef, Zane) for a six-month programme. Each mentor takes exactly one new hire. Wren mentors Sam. Xia will only mentor Ravi. Yousef refuses to mentor Quinn.

Which of the following pairings of new hires with mentors is consistent with all the constraints?',
    NULL,
    NULL,
    'A',
    'Wren mentors Sam and Xia mentors Ravi. That leaves Yousef and Zane to pair with Priya and Quinn. Yousef refuses Quinn, so Yousef = Priya and Zane = Quinn. Final pairing: Priya-Yousef, Quinn-Zane, Ravi-Xia, Sam-Wren — option A. Option B swaps Yousef and Zane, breaking the Yousef/Quinn constraint. Option C places Priya with Xia (only Ravi allowed). Option D puts Quinn with Wren and Sam with Zane, breaking Wren=Sam.',
    23,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
