  -- [30] Restaurant Bills
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '63722588-0278-480b-8b32-59aa010c89d8',
    'Restaurant Bills',
    'logic_puzzle'::dm_question_type,
    'A group of five diners — Anya, Bo, Cal, Devi and Eve — split the cost of their meal. The mean cost per diner is £20. Anya''s bill is £4 more than Bo''s. Bo''s bill is £2 more than Cal''s. Devi''s bill is £4 more than Cal''s. Eve''s bill is £8 less than Anya''s.

How much did Anya pay?',
    NULL,
    NULL,
    'D',
    'Total = 5 × £20 = £100. Let Cal''s bill = C. Then Bo = C + 2, Anya = Bo + 4 = C + 6, Devi = C + 4 and Eve = Anya − 8 = C − 2. Sum = (C+6) + (C+2) + C + (C+4) + (C−2) = 5C + 10 = 100, so C = 18. Anya = 18 + 6 = £24.',
    30,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

