  -- [33] Lab Door Mystery
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '6b6d2093-362d-4512-9348-960ebeb907c0',
    'Lab Door Mystery',
    'logic_puzzle'::dm_question_type,
    'Four students — Wren, Xia, Yaz, Zed — each made a statement about who broke the lab door. Each student either always tells the truth or always lies. Exactly one student broke the door, and exactly one student is lying. Wren says: ''I did not break the door.'' Xia says: ''I did not break the door.'' Yaz says: ''Wren is lying.'' Zed says: ''Xia is telling the truth.''

Who broke the lab door?',
    NULL,
    NULL,
    'D',
    'If Yaz is the liar, then Wren is truthful — Wren did not break it, and Xia truthfully did not break it. Zed truthfully confirms Xia. That leaves Zed as the only possible breaker, and the pattern is self-consistent. Test any other liar: if Wren lies then Wren broke it, but Yaz truthfully says Wren is lying — already two truths that rule out Wren''s confession, so the chain fails on counts. If Xia lies, then Xia broke it, but Zed truthfully says Xia is telling the truth — contradiction. If Zed lies, Xia is actually lying too, breaking the one-liar rule. Only Zed works as the breaker.',
    33,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Wren', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Xia', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Yaz', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Zed', NULL, 4, NULL
  );

  -- [34] Later Sunday Openings
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '5d51ad38-f496-437c-b2b5-5ca2e02226c1',
    'Later Sunday Openings',
    'recognising_assumptions'::dm_question_type,
    'Should UK retail chains delay Sunday trading hours to start at 11am instead of earlier, to improve the wellbeing of retail staff?',
    NULL,
    NULL,
    'B',
    'B connects the action (11am Sunday starts) to the outcome (staff wellbeing) with workforce health data. A addresses shopper preference, not wellbeing. C focuses on "some" staff — a narrow group, not the full workforce. D addresses revenue, not wellbeing.',
    34,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; many shoppers prefer to shop later on Sundays anyway.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; a 2022 review of UK retail workforce health found an 11am Sunday start improved reported sleep quality by 18% and reduced staff sick days by 9%, directly improving staff wellbeing.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; some retail staff prefer starting early on Sundays so that they can finish earlier.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; retail chains would lose revenue from customers who shop before 11am.', NULL, 4, NULL
  );

  -- [35] Keys, Inspections and Certificates
