  -- [36] Quiz Team Selection
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '078d5686-3b4b-424f-81fb-d05cd3d5525a',
    'Quiz Team Selection',
    'logic_puzzle'::dm_question_type,
    'A firm picks an 8-member inter-department quiz team. Each of four departments contributes exactly 2 members, split evenly between one junior and one senior. A fair draw resolves any department with more nominations than slots. The nominations are shown in the table below.

Which of the following lists the volunteers who take part in the fair draw?',
    '{"headers":["Department","Juniors nominated","Seniors nominated"],"rows":[["Marketing","Alice","Bob"],["Finance","Dev","Ella, Fran"],["IT","Gia","Hal"],["HR","Iris","Jon"]]}'::jsonb,
    NULL,
    'B',
    'Each department must produce 1 junior and 1 senior. Marketing, IT, and HR each have exactly 1 junior and 1 senior — no draw needed. Finance has 1 junior (Dev, exact) and 2 seniors (Ella, Fran) for 1 senior slot — Ella and Fran go to the fair draw. Option B.',
    36,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Alice and Bob', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Ella and Fran', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
