  -- [37] Running Club Disciplines
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'f11fa335-7ec9-434f-857e-be39ab68c61b',
    'Running Club Disciplines',
    'venn_diagram'::dm_question_type,
    'A running club has 80 members. 34 members compete in road races, 35 in trail races, and 28 in track races. 14 members compete in both road and trail. 10 members compete in both road and track. 9 members compete in both trail and track. 5 members compete in all three disciplines. 11 members do not compete in any of the three disciplines.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'A',
    'Freebies: 5 compete in all three (the centre) and 11 compete in none (outside). Scan — B shows 3 in the centre, eliminate B. C shows 13 outside, eliminate C. That leaves A and D. The stem says 14 compete in both road and trail, 5 of whom also do track, so road-and-trail only = 14 − 5 = 9. A shows 9 there. D shows 7 there — eliminate D. Answer: A.',
    37,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

