  -- [39] Independent Alarms
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '9bde4832-a583-4563-8ac7-e7c2c26247ed',
    'Independent Alarms',
    'probabilistic'::dm_question_type,
    'A warehouse has two independent smoke alarms. Alarm X correctly triggers in 90% of fires. Alarm Y correctly triggers in 80% of fires.

What is the probability that at least one alarm triggers in the event of a fire?',
    NULL,
    NULL,
    'C',
    'P(neither triggers) = P(X fails) × P(Y fails) = 0.10 × 0.20 = 0.02. P(at least one triggers) = 1 − 0.02 = 0.98 = 98%.',
    39,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

