  -- [41] Rare Allergy Screen
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '3bfe9c6b-eea8-4578-845a-46d692db8d5e',
    'Rare Allergy Screen',
    'probabilistic'::dm_question_type,
    'A food allergy affects 1 in 500 adults. A screening test correctly identifies 98% of adults who have the allergy and correctly identifies 95% of adults who do not. An adult tests positive.

Approximately what is the probability that this adult actually has the allergy?',
    NULL,
    NULL,
    'B',
    'Consider 50,000 adults: 100 have the allergy, 49,900 do not. True positives = 98% of 100 = 98. False positives = 5% of 49,900 = 2,495. Total positives = 98 + 2,495 = 2,593. Probability of having the allergy given a positive test = 98 / 2,593 ≈ 0.038, so around 4%.',
    41,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

