  -- [43] Gluten-Free Aisle
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '966e1895-c1eb-4e8d-a294-99689e3e4728',
    'Gluten-Free Aisle',
    'syllogism'::dm_question_type,
    'If a product is labelled ''gluten-free'', it contains no wheat, barley, or rye. All products in aisle 4 are labelled ''gluten-free''. The oat biscuits in aisle 6 are not labelled ''gluten-free''. Some of the oat biscuits contain no wheat.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    43,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'No product in aisle 4 contains wheat.', 'Yes', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'The oat biscuits in aisle 6 contain wheat.', 'No', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'A product that contains barley is not labelled ''gluten-free''.', 'Yes', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'All products in aisle 6 are oat biscuits.', 'No', 4
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Some oat biscuits are safe for people avoiding all gluten grains.', 'No', 5
  );

  -- [44] Westgate Library Loans
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '0f12e298-43e8-44eb-98ee-6808e5798321',
    'Westgate Library Loans',
    'syllogism'::dm_question_type,
    'Only members of Westgate Library may borrow reference books. A member who has borrowed a reference book cannot borrow another reference book unless the first has been returned. Every reference book has a yellow spine sticker. All reference books are shelved on the second floor.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    44,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Anyone who has borrowed a reference book must be a member of Westgate Library.', 'Yes', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Every book with a yellow spine sticker is a reference book.', 'No', 2
  );
  INSERT INTO decision_making_question_statements
