  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'For a member to borrow a second reference book, they must first return the first one.', 'Yes', 5
  );

  -- [45] Community Centre Evenings
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '1dda2ac3-bfa8-466e-9da3-b36b7214cec5',
    'Community Centre Evenings',
    'venn_diagram'::dm_question_type,
    'A community centre surveys 90 members about three evening activities. 35 attend yoga, 40 attend book club, 25 attend swimming. 10 members attend both yoga and book club. 12 members attend both book club and swimming. No member attends both yoga and swimming.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'A',
    'Freebies: the stem gives 10 in the yoga-and-book-club overlap and 12 in the book-club-and-swimming overlap. Scan — B shows 14 in the yoga-and-book-club overlap, not 10 — eliminate B. C shows 8 in the book-club-and-swimming overlap, not 12 — eliminate C. That leaves A and D. Yoga-only = 35 − 10 = 25; A shows 25 ✓, D shows 21 — eliminate D. Answer: A.',
    45,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

