  -- [49] Festival Camping Plots
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'caccce6f-6f7f-49e3-a655-00cc254a8f41',
    'Festival Camping Plots',
    'logic_puzzle'::dm_question_type,
    'Six tents are arranged on a 2-row by 3-column grid (positions 1 to 3 in the top row, positions 4 to 6 in the bottom row). Hari''s tent is directly above Joel''s. Mira is in position 4 (the bottom-left corner). Naveen is to the immediate right of Mira. Owen is in the same row as Hari. Pia takes the remaining tent.

Which two people are guaranteed to be in the same column as each other?',
    NULL,
    NULL,
    'D',
    'Mira is in position 4 and Naveen in position 5. Hari sits directly above Joel, so Hari is in the top row and Joel is in the bottom row in the same column. Joel cannot be position 4 (Mira) or position 5 (Naveen), so Joel = 6 and Hari = 3. Owen is in the same row as Hari, so Owen is in the top row (position 1 or 2), and Pia takes the other top-row spot. Hari and Joel are always in column 3 together. Owen versus Naveen and Pia versus Mira each depend on which top-row spot Owen and Pia take, so they are not guaranteed.',
    49,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Hari and Mira', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Owen and Naveen', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Pia and Mira', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Hari and Joel', NULL, 4, NULL
  );

