  -- [59] Round-Robin Tennis Points
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'abbc256d-63e6-441c-9af6-af721c6caa7a',
    'Round-Robin Tennis Points',
    'logic_puzzle'::dm_question_type,
    'In a round-robin tennis tournament, five players each play every other player exactly once. A win awards 2 points to the winner and 0 to the loser; a drawn match awards 1 point to each player. At the end of the tournament, four of the players have scored 5 points each.

How many points did the fifth player score?',
    NULL,
    NULL,
    'A',
    'Five players playing every other player once gives 10 matches in total. Every match awards 2 points in total (either 2 + 0 or 1 + 1), so the tournament distributes 20 points. If four players have scored 5 each, that is 20 points accounted for — leaving 0 points for the fifth player.',
    59,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

