  -- [61] Art Class Levels
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'd8244ff0-c19c-41fa-9138-677ec5a076b3',
    'Art Class Levels',
    'venn_diagram'::dm_question_type,
    'A school has 240 students registered across four art class levels. 80 attend beginner, 65 attend intermediate, 55 attend advanced, and 40 attend masterclass. 25 students attend both beginner and intermediate. 20 students attend both intermediate and advanced. 15 students attend both advanced and masterclass. 60 students do not attend any of these levels.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'A',
    'Two freebies: the stem gives 25 students attending beginner and intermediate, and 15 students attending advanced and masterclass. Scan — B shows 15 in the beginner-and-intermediate overlap and 25 in the advanced-and-masterclass overlap, the two numbers swapped — eliminate B. C shows 58 outside, not the stated 60 — eliminate C. That leaves A and D. The stem also gives 20 students attending intermediate and advanced. D shows 18 in that overlap — eliminate D. A matches every stated overlap and total. Answer: A.',
    61,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

