  -- [63] Who Broke the Vase
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'b53bdd95-4cc5-40cb-83a9-75987d5dd428',
    'Who Broke the Vase',
    'logic_puzzle'::dm_question_type,
    'Four people at a shop — Ava, Ben, Cai, and Dee — are each suspected of breaking a vase. Exactly one of them broke it, and each makes one statement. Three of the statements are true and one is false.

Ava says: ''Ben broke it.''
Ben says: ''Dee broke it.''
Cai says: ''I did not break it.''
Dee says: ''Ben is lying.''

Who broke the vase?',
    NULL,
    NULL,
    'B',
    'Suppose Ben told the truth: then Dee broke it. Ava''s claim "Ben broke it" is then false, and Dee''s claim "Ben is lying" is also false — two false statements, breaking the one-liar rule. So Ben is the liar, and "Dee broke it" is false. The other three statements must all be true: Ava''s "Ben broke it" is true, so Ben broke the vase. Cai''s "I did not break it" and Dee''s "Ben is lying" are consistent.',
    63,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Ava', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Ben', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Cai', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Dee', NULL, 4, NULL
  );

  -- [64] Cubicle Productivity Survey
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '9c54f773-6b21-4157-be29-6fedbc12af51',
    'Cubicle Productivity Survey',
    'interpreting_info'::dm_question_type,
    'A business research firm surveyed 500 office workers before and after their company moved them from an open-plan layout to private cubicles. After the move, 62% of respondents reported feeling more productive. Only 8% reported feeling less productive, and the remainder reported no change. The firm''s report concludes that private cubicles cause improvements in productivity, though some commentators argue the change may reflect the novelty of the new layout and predict that perceived benefits will fade within a year.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    64,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'More than half of the surveyed workers reported feeling more productive after the move.', 'Yes', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Perceived productivity gains from the cubicle layout will have disappeared within twelve months of the move.', 'No', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Measured productivity rose after the office layout was changed.', 'No', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'The survey recorded views from the same group of workers before and after the layout change.', 'Yes', 4
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Open-plan desks are less suitable for productivity than private cubicles.', 'No', 5
  );

