  -- [66] Mandatory Cycle Helmets
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '7c526657-fc73-4fa8-b348-f3afa1893de5',
    'Mandatory Cycle Helmets',
    'recognising_assumptions'::dm_question_type,
    'Should cycle helmets be made legally mandatory for all cyclists in the UK to reduce cycling-related head injuries?',
    NULL,
    NULL,
    'A',
    'A directly links the action (mandatory helmets) to the outcome (cycling head injuries) with peer-reviewed evidence and a concrete modelled reduction. B is emotional stereotyping and does not address head injury rates. C addresses comfort, not head injuries. D is a principle of personal freedom, not an argument about the outcome.',
    66,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; peer-reviewed studies show helmet use reduces cycling-related head-injury risk by around 60%, and modelling based on UK cycling volumes suggests a mandatory law would prevent around 2,000 head injuries per year.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
