  -- [70] Single-use Cup Levy
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '5e2a1f18-260c-4af5-b3d4-177cdbd1d2bc',
    'Single-use Cup Levy',
    'recognising_assumptions'::dm_question_type,
    'Should single-use takeaway cups be subject to a nationwide levy to reduce littering in urban parks?',
    NULL,
    NULL,
    'B',
    'B links the action (nationwide cup levy) to the outcome (park litter) with a measured 34% drop in discarded cups after a similar Irish levy. A addresses café branding rather than litter. C assumes a substitution effect without evidence and diverts to a different waste type. D addresses enforcement cost, not the litter outcome.',
    70,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; many cafés are keen to appear environmentally responsible.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; a 25p levy introduced in Ireland led to a 34% reduction in discarded takeaway cups in Dublin''s public parks within twelve months, directly cutting park litter.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; customers would simply switch to disposable plastic bottles, creating a different kind of waste.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; enforcing a levy in every urban area would require additional staff.', NULL, 4, NULL
  );

