  -- [81] Universal Free School Meals
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'ab9abe49-a6d1-4b52-b575-2cbdaa63e7a7',
    'Universal Free School Meals',
    'recognising_assumptions'::dm_question_type,
    'Should all UK primary school pupils receive free school meals regardless of family income, in order to improve their educational attainment?',
    NULL,
    NULL,
    'A',
    'A links the action (free universal meals) to the outcome (educational attainment) using a direct pilot study result. B addresses parental convenience, not attainment. C raises cost, which is about feasibility rather than attainment. D addresses preference, not attainment.',
    81,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; a four-year government pilot of universal free school meals recorded an 8% rise in pupils'' average reading and maths scores compared to a matched control group.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; many parents find packing school lunches stressful in the mornings.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; schools already have enough costs to cover and cannot afford a universal meal programme.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; not every pupil wants to eat school-provided food rather than their own lunch.', NULL, 4, NULL
  );

