  -- [84] Office Allocation
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '23f6ecc3-ce55-4e24-8deb-6e64d2ced0e6',
    'Office Allocation',
    'logic_puzzle'::dm_question_type,
    'A small firm has four staff — Reza, Salma, Toby and Una — who must each be assigned to exactly one of four offices labelled 1, 2, 3 and 4. Una takes office 3. Toby''s office number is no greater than 2. Salma''s office number is greater than Toby''s. Reza takes an office with a lower number than Toby''s.

Which of the following is the correct office assignment?',
    NULL,
    NULL,
    'A',
    'Una = 3. Toby is in office 1 or 2. If Toby = 1, then Reza must be lower than 1, which is impossible, so Toby = 2. Reza < 2 means Reza = 1. The only office left for Salma is 4, which satisfies Salma > Toby. So the unique assignment is Reza in 1, Toby in 2, Una in 3, Salma in 4.',
    84,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Reza in 1, Toby in 2, Una in 3, Salma in 4', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Reza in 2, Salma in 1, Una in 3, Toby in 4', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Reza in 1, Salma in 2, Una in 3, Toby in 4', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Reza in 4, Salma in 2, Toby in 1, Una in 3', NULL, 4, NULL
  );

