  -- [88] Primary Cooking Lessons
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '0f8aedd6-60ed-4aea-bf9f-8456a7ed9b30',
    'Primary Cooking Lessons',
    'recognising_assumptions'::dm_question_type,
    'Should primary schools in the UK introduce a compulsory weekly cooking lesson to improve pupils'' long-term dietary choices?',
    NULL,
    NULL,
    'B',
    'B ties the action (compulsory cooking lessons) to the outcome (long-term dietary choices) with a five-year follow-up study showing measurable impact at age 16. A addresses enjoyment, not dietary choices. C relies on an assumption about home cooking and uses ''many'' rather than all. D raises curriculum logistics, not the dietary outcome.',
    88,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; children often enjoy hands-on lessons.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; a five-year follow-up study of a UK cooking-lesson programme found that participating pupils were 31% more likely to eat a balanced diet at age 16 than non-participants, directly improving long-term dietary choices.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; many parents already teach their children to cook at home.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; schools do not have enough curriculum time for additional compulsory lessons.', NULL, 4, NULL
  );

  -- [89] Street House Numbers
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '2cf4a812-6688-4fbe-9f8b-67382edd0068',
    'Street House Numbers',
    'logic_puzzle'::dm_question_type,
    'Four houses sit in a row on one side of a street, numbered 1, 3, 5, and 7 from left to right. The Aran, Bruno, Chen, and Dumas families each live in one of these houses, one family per house. The Bruno family lives at a lower number than the Aran family. The Chen family does not live at an end house. The Dumas family lives at number 7. The Aran family does not live next to the Dumas family.

Which family lives at number 1?',
    NULL,
    NULL,
    'B',
    'Dumas = 7 (given). Aran is not next to Dumas, so Aran ≠ 5, meaning Aran is at 1 or 3. Bruno''s number must be lower than Aran''s, so Aran cannot be at 1 — that leaves Aran = 3 and Bruno = 1. Chen is not at an end, so Chen = 5 (the only remaining middle number). Bruno at number 1.',
    89,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Aran', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Bruno', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Chen', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Dumas', NULL, 4, NULL
  );

