  -- [92] Coffee Roastery Beans
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '9981ffdd-f634-4eef-a7a5-2e59eb68a9fa',
    'Coffee Roastery Beans',
    'venn_diagram'::dm_question_type,
    'A roastery sorts 60 batches of beans by three labels. 24 are single origin, 20 are decaffeinated and 22 are organic. 7 batches are both single origin and decaffeinated, 8 are both single origin and organic, and 6 are both decaffeinated and organic. 3 batches carry all three labels. 12 batches do not fall under any of these labels.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'A',
    'Freebies from the stem: 3 batches sit in the centre (all three labels) and 12 sit outside any label. Scan the options. B shows 5 in the centre — eliminate B. C shows 9 outside — eliminate C. That leaves A and D. The decaffeinated-and-organic-only region equals 6 minus the 3 that also have single origin = 3. D shows 6 there (it forgot to subtract the triple) — eliminate D. A shows 3 — correct.',
    92,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

