  -- [93] Four-Day School Week
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '05de0870-8885-4569-9ee5-80fa7551d8b7',
    'Four-Day School Week',
    'recognising_assumptions'::dm_question_type,
    'Should secondary schools introduce a four-day school week to improve student well-being?',
    NULL,
    NULL,
    'A',
    'A is the strongest: it addresses the action (four-day week) and the outcome (student well-being) with trial evidence of an 18 per cent fall in self-reported anxiety and no loss in academic results. B addresses teacher benefits, not student well-being. C addresses parental childcare, a separate outcome. D addresses perceived necessity — it neither measures well-being nor engages with whether the change would improve it.',
    93,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; trials in two Scottish secondary schools reported student-reported anxiety scores fell 18 per cent after a four-day week was introduced, with no change in academic results.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; teachers will benefit from having an extra day off each week.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; parents with full-time jobs may struggle to arrange childcare for the extra day.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; students already have long summer breaks, so adding another day off is unnecessary.', NULL, 4, NULL
  );

  -- [94] Project Assignment
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'c20960ac-e644-4a8a-8067-0af765ac9ce5',
    'Project Assignment',
    'logic_puzzle'::dm_question_type,
    'Four employees (Mia, Noor, Omar, Paul) are each assigned to exactly one of four projects (Red, Blue, Green, Yellow). Each project has exactly one employee. Mia will not take Red. Noor takes either Red or Green. Omar takes Yellow if and only if Mia takes Blue. Paul does not take Green.

Which of the following assignments is consistent with all the constraints?',
    NULL,
    NULL,
    'A',
    'Mia is not on Red. Try Mia on Blue — then Omar must take Yellow (the biconditional). Noor takes Red or Green; Paul does not take Green, so Paul must take Red — but if Paul takes Red then Noor must take Green (the remaining option), satisfying the Noor constraint. Assignment: Mia Blue, Paul Red, Noor Green, Omar Yellow — option A. Option B puts Paul on Green. Option C puts Mia on Red. Option D puts Omar on Yellow without Mia on Blue, violating the biconditional.',
    94,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Mia: Blue, Noor: Green, Omar: Yellow, Paul: Red', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Mia: Blue, Noor: Red, Omar: Yellow, Paul: Green', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Mia: Red, Noor: Green, Omar: Yellow, Paul: Blue', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Mia: Green, Noor: Red, Omar: Yellow, Paul: Blue', NULL, 4, NULL
  );

