  -- [97] Gardening Club Tools
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '08f6de5b-d42d-4316-aa92-10d116d5685c',
    'Gardening Club Tools',
    'venn_diagram'::dm_question_type,
    'A gardening club has 60 members. 28 use spades, 24 use forks, and 22 use rakes. 10 members use both spades and forks. 8 use both spades and rakes. 6 use both forks and rakes. 4 members use all three tools. 6 members use none of the three tools.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'A',
    'Freebies: 4 use all three (the centre) and 6 use none (outside). Scan — B shows 3 in the centre, not 4, so eliminate B. C shows 8 outside, not 6, so eliminate C. That leaves A and D. The stem says 10 use both spades and forks, 4 of whom also use rakes, so spades-and-forks only = 10 − 4 = 6. A shows 6 there, D shows 8 — eliminate D. Answer: A.',
    97,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

