  -- [98] Seminar Rooms
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'd1fb27dc-3b7d-451c-a86b-06630764f8ff',
    'Seminar Rooms',
    'logic_puzzle'::dm_question_type,
    'Four seminars — Logic, Maths, Physics, and Biology — are running at the same time in four rooms in a row numbered 1 to 4 from left to right. Logic is not in Room 1. Maths and Physics are in adjacent rooms. Biology is immediately to the right of Maths. Physics is not in Room 4.

Which seminar is in Room 4?',
    NULL,
    NULL,
    'A',
    'Biology immediately right of Maths gives (Maths, Biology) on rooms (1,2), (2,3), or (3,4). Maths and Physics must be adjacent. If Maths = 1, Physics would need to be 2 but Biology is there — fails. If Maths = 3, Biology = 4 and Physics = 2, but Logic would then be in Room 1 — fails. So Maths = 2, Biology = 3, Physics = 1 (adjacent to Maths), and Logic = 4.',
    98,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Logic', NULL, 1, NULL
  );
