  -- [104] Distinction Necessary
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'cf9cf65f-64bd-473f-9f6e-0c6f00bb09b5',
    'Distinction Necessary',
    'syllogism'::dm_question_type,
    'Achieving a distinction in the chemistry exam is necessary to qualify for the advanced cohort. A grade of 80% or above on the exam is sufficient to be awarded a distinction. Most candidates who study with a tutor score above 80%. No candidate who fails the practical assessment can join the advanced cohort.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    104,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Every candidate in the advanced cohort has achieved a distinction.', 'Yes', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Every candidate who scores 80% on the chemistry exam will join the advanced cohort.', 'No', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Most candidates who study with a tutor have achieved a distinction.', 'Yes', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Anyone who has not achieved a distinction has failed the practical assessment.', 'No', 4
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'If a candidate joined the advanced cohort, they passed the practical assessment.', 'Yes', 5
  );

  -- [105] Later School Start
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'febf7e7d-7e43-4786-b59d-c699efa21dae',
    'Later School Start',
    'recognising_assumptions'::dm_question_type,
    'Should secondary schools in the UK move the start of the school day from 08:45 to 10:00 to improve student academic performance?',
    NULL,
    NULL,
    'B',
    'B connects the action (later start) to the outcome (academic performance) with study evidence. A addresses preference, not performance. C addresses logistics, not performance. D assumes teaching quality is the only relevant factor and doesn''t address whether a later start could still help.',
    105,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; teenagers tend to get up late at the weekend, so they would prefer a later start.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; multiple controlled studies have shown that moving start times to after 09:30 increases average exam scores by around 4% in secondary-age students, directly improving academic performance.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; parents of younger children would need to rearrange school runs, causing logistical problems.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; academic performance depends on teaching quality, which a later start will not change.', NULL, 4, NULL
  );

  -- [106] Unlabelled Bakery Cakes
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'ceb1c2cb-9052-4a64-ba34-58c74501bb56',
    'Unlabelled Bakery Cakes',
    'venn_diagram'::dm_question_type,
    'A bakery has 90 cakes. 30 are sponge, 25 are chocolate, and 20 are gluten-free. 10 cakes are both sponge and chocolate. 9 cakes are both sponge and gluten-free. 8 cakes are both chocolate and gluten-free. 6 cakes are in all three categories. 36 cakes are plain.

Which of the following diagrams is consistent with the data?',
    NULL,
    NULL,
    'A',
    'Two freebies: 6 cakes are in all three categories (the centre triple overlap) and 36 cakes are plain (outside). Scan — B shows 4 in the centre — eliminate B. C shows 42 outside — eliminate C. That leaves A and D. Each shape''s regions must sum to its category total (sponge 30, chocolate 25, gluten-free 20). In D, the three shape totals come out as 29, 24, and 22 — none of them match the stated totals. In A, the three shapes sum to 30, 25, and 20 as required. Answer: A.',
    106,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

