  -- [107] Charity Shop Tiers
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '3aad7b8e-152b-4613-a705-e71a664dde8a',
    'Charity Shop Tiers',
    'logic_puzzle'::dm_question_type,
    'A charity shop sold 40 items one day. Five items sold at £20 each. Twelve items sold at £5 each. The remaining items were split between a £3 tier and a £12 tier, with exactly three more items at the £3 tier than at the £12 tier.

How many items sold at the £3 tier?',
    NULL,
    NULL,
    'C',
    'After the £20 and £5 items, 40 − 5 − 12 = 23 items remain. Let the £12 count be y and the £3 count be y + 3. Then y + (y + 3) = 23, giving 2y = 20, so y = 10 and the £3 tier has y + 3 = 13 items.',
    107,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', '10', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', '11', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', '13', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', '16', NULL, 4, NULL
  );

  -- [108] Biased Coin Triple
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'ca009d11-0f00-411b-a051-328364d5cdc8',
    'Biased Coin Triple',
    'probabilistic'::dm_question_type,
    'A coin is biased so that it lands heads with probability 0.6 and tails with probability 0.4. It is flipped three times, and each flip is independent.

What is the probability of getting heads on all three flips?',
    NULL,
    NULL,
    'A',
    'Independent events multiply: P(all three heads) = 0.6 × 0.6 × 0.6 = 0.216.',
    108,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', '0.216', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
