  -- [111] Cycle Helmet Law
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'b7cd43b2-b43c-4ce3-a170-835d8f88e6bd',
    'Cycle Helmet Law',
    'recognising_assumptions'::dm_question_type,
    'Should it be made compulsory for all adult cyclists to wear helmets to reduce head injuries on UK roads?',
    NULL,
    NULL,
    'A',
    'A directly links the action (mandatory helmets) to the outcome (reduced head injuries) with specific evidence. B addresses practicality but not head injuries. C is opinion-based and narrow. D addresses a tangential outcome (physical activity) rather than head injuries. A is the strongest.',
    111,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; a 2022 review of UK hospital data found cyclists wearing helmets had 45% fewer serious head injuries than those without, so a legal requirement would directly reduce head injuries.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; helmets are inexpensive and most cyclists already carry one.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; some cyclists find helmets uncomfortable on long rides.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; mandatory helmet laws discourage some people from cycling, which reduces physical activity across the population.', NULL, 4, NULL
  );

  -- [112] Disaster Response Team
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '613ee2c7-e91e-41f8-8c91-c39e3b7c7f34',
    'Disaster Response Team',
    'logic_puzzle'::dm_question_type,
    'A 16-person disaster response team will be drawn from four fire watches. The volunteers are listed below.

Watch Alpha: Paramedics — Maya, Sam; Engineers — Leo, Finn.
Watch Bravo: Paramedics — Ava, Nate; Engineers — Kai, Ezra.
Watch Charlie: Paramedics — Gus, Isla, Rhea; Engineers — Mae, Pia.
Watch Delta: Paramedics — Ben, Tess; Engineers — Ruby, Ola.

The team must contain exactly 4 members from each watch, with an equal split of paramedics and engineers. Where a watch has more volunteers than its quota in a role, a selection exercise decides who is chosen.

Which volunteers sit the selection exercise?',
    NULL,
    NULL,
    'A',
    'Each watch needs 2 paramedics and 2 engineers. Alpha, Bravo, and Delta each have exactly 2 of each — no selection needed. Charlie has 3 paramedics (Gus, Isla, Rhea) for 2 places, so those three sit the exercise. Charlie''s two engineers (Mae, Pia) already fill the two engineer places.',
    112,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Gus, Isla, and Rhea', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Gus and Isla only', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Mae and Pia', NULL, 3, NULL
