  -- [113] Spinner Sums
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'ee73e3bf-e783-4277-a852-3e0af24b5b89',
    'Spinner Sums',
    'probabilistic'::dm_question_type,
    'A fair spinner is divided into eight equal sectors numbered 1 to 8. The spinner is spun twice and the two results are recorded.

What is the probability that the sum of the two spins is greater than 12?',
    NULL,
    NULL,
    'A',
    'There are 8 × 8 = 64 equally likely outcomes. Pairs (a, b) with a + b > 12: sum 13 has (5,8), (6,7), (7,6), (8,5) = 4; sum 14 has (6,8), (7,7), (8,6) = 3; sum 15 has (7,8), (8,7) = 2; sum 16 has (8,8) = 1. Total favourable = 10. Probability = 10 / 64 = 5/32.',
    113,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
