  -- [115] Sugary Drinks Warning Labels
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '9c256236-770a-45db-8c48-165262a663f1',
    'Sugary Drinks Warning Labels',
    'recognising_assumptions'::dm_question_type,
    'Should sugary soft drinks be required to carry prominent warning labels to reduce the rate of childhood obesity in the UK?',
    NULL,
    NULL,
    'B',
    'B connects the action (warning labels on sugary drinks) directly to the outcome (childhood obesity) with a specific trial showing reduced sugar consumption in primary-age children. A addresses parental knowledge rather than obesity rates. C uses speculative language (''might be ignored'') without evidence. D deflects by citing other obesity factors instead of assessing whether the labels themselves help.',
    115,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; many parents are unsure whether fizzy drinks are unhealthy.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; a 2022 trial of warning labels on sugary drinks in Chilean schools reduced total sugar consumption by primary-age children by 24%, directly lowering the leading dietary driver of childhood obesity.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; warning labels might be ignored by shoppers who have always bought the same drinks.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; childhood obesity also depends on exercise and genetics, which warning labels cannot change.', NULL, 4, NULL
  );

  -- [116] Vorms and Trels
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'fcd5f1b9-d6b9-40ba-b1c3-a914e72c9a10',
    'Vorms and Trels',
    'syllogism'::dm_question_type,
    'All vorms are trels. No trel is a glink. Some sloons are vorms. Most glinks are quemps.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    116,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'No vorm is a glink.', 'Yes', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Some sloons are trels.', 'Yes', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'All glinks are quemps.', 'No', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Some quemps are not glinks.', 'No', 4
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Some trels are glinks.', 'No', 5
  );

  -- [117] Hardware Store Fasteners
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '13e911db-6288-4dc8-994a-dcba7333271b',
    'Hardware Store Fasteners',
    'interpreting_info'::dm_question_type,
    'A hardware store has 60 fasteners on a single shelf. Two-thirds of the fasteners are screws and the rest are bolts. Of the screws, every one with a flat head is countersunk. None of the bolts are countersunk. Some of the screws are stainless steel.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    117,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'All countersunk fasteners on the shelf are screws.', 'Yes', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Every screw on the shelf is countersunk.', 'No', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Some of the screws on the shelf are not stainless steel.', 'Yes', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Exactly 20 fasteners on the shelf are stainless steel.', 'No', 4
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'All flat-head fasteners on the shelf are screws.', 'No', 5
  );

  -- [118] Calorie Labels in Restaurants
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '19ba8ffa-bcb5-4c16-87d3-c61700298228',
    'Calorie Labels in Restaurants',
    'recognising_assumptions'::dm_question_type,
    'Should all chain restaurants in the UK be required to display calorie information on their menus to reduce the prevalence of overweight adults?',
    NULL,
    NULL,
    'B',
    'B addresses both parts of the proposition with study data linking labelling to a measurable decline in overweight prevalence among regular diners. A appeals to a principle of right to know, which does not address the overweight prevalence outcome. C addresses menu creativity, which is tangential to the outcome. D relies on an unsupported assumption that diners are already aware of calorie content.',
    118,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; customers have the right to know what they are eating before they make their order at a restaurant.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; a 2023 study found restaurants required to label calories saw average meal calorie selection drop by 8%, and follow-up data showed a measurable decline in overweight prevalence among regular diners over two years.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; chefs would be forced to standardise their recipes to give accurate calorie counts, reducing menu creativity.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; people who choose to eat at restaurants are typically already aware of which menu items are higher in calories, so adding labels will not change their decisions.', NULL, 4, NULL
  );

