  -- [120] University Research Funding Review
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'd078bd5a-d15f-4953-b5ee-acbff6b30a53',
    'University Research Funding Review',
    'interpreting_info'::dm_question_type,
    'A 2024 review of UK university research argues that the recent decline in domestic public funding has been partially offset by an increase in private industry partnerships. The reviewers note that, between 2018 and 2023, average government grant income per institution fell by 11% while average industry-sponsored research income rose by 28%. The reviewers also highlight that private partnerships have, in their words, concentrated in applied research areas with near-term commercial value, and they suggest that this trend has likely contributed to a 14% reduction in the share of grants awarded to early-career fundamental research over the same period. Critics of the review caution that correlation does not prove causation in this last claim.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    120,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
