  -- [121] Rare Condition Screening
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '3e40da81-93b0-4506-b104-8a3f53914d84',
    'Rare Condition Screening',
    'probabilistic'::dm_question_type,
    'A rare condition affects 2 in every 1,000 people in a population. A screening test correctly identifies the condition 95% of the time when it is present, and correctly returns a negative result 90% of the time when the condition is absent. One person is chosen at random from the population and tests positive.

Approximately what is the probability that this person actually has the condition?',
    NULL,
    NULL,
    'A',
    'Imagine 10,000 people. 0.2% have the condition = 20 people; 9,980 do not. Of the 20, 95% test positive = 19 true positives. Of the 9,980, 10% test positive (since specificity is 90%) = 998 false positives. Total positives = 19 + 998 = 1,017. P(has condition | positive) = 19 / 1,017 ≈ 1.9%, roughly 2%. The test''s apparent accuracy is dwarfed by the base rate — most positives are false positives.',
    121,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'About 2%', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'About 50%', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'About 85%', NULL, 3, NULL
  );
