    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'About 95%', NULL, 4, NULL
  );

  -- [122] Community Programme Pairs
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'de96eb9b-7e68-4672-a1e2-3bfd61180aab',
    'Community Programme Pairs',
    'venn_diagram'::dm_question_type,
    'A community hub runs four programmes: yoga, choir, chess and pottery. 120 residents take part in total. Some residents attend both yoga and choir. Some residents attend both chess and pottery. No resident attends any other combination of these programmes. 30 attend yoga only, 25 attend choir only, 20 attend chess only, 15 attend pottery only. 18 attend both yoga and choir, 12 attend both chess and pottery.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'A',
    'Freebies: 18 residents in the yoga-choir overlap and 12 in the chess-pottery overlap. Scan — B shows 14 in the yoga-choir overlap, not 18 — eliminate B. C shows 10 in the chess-pottery overlap, not 12 — eliminate C. That leaves A and D. The stem says 30 attend yoga only; D shows 28 — eliminate D. A has every stated figure and sums to 120. Answer: A.',
    122,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

