  -- [123] Smartphones in Primary Schools
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '91be2030-b663-4ee8-82fb-e143f44bed04',
    'Smartphones in Primary Schools',
    'recognising_assumptions'::dm_question_type,
    'Should UK primary schools ban pupils from using personal smartphones during the school day to improve classroom concentration?',
    NULL,
    NULL,
    'B',
    'B links the action (the smartphone ban) to the outcome (classroom concentration) with a randomised trial using task-completion measures. A is tangential — it addresses home rather than the classroom. C is a partial-scope exception that does not engage with concentration outcomes. D relies on an unsupported assumption about primary pupils'' susceptibility to distraction.',
    123,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; parents often worry about their children''s screen time at home.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; a 24-school randomised trial in the UK found that classrooms enforcing a smartphone ban scored 18% higher on task-completion measures across English and maths than matched classrooms without the ban.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; some pupils occasionally need to contact parents in emergencies.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; primary-age pupils are too young to be distracted by smartphones in the first place.', NULL, 4, NULL
  );

  -- [124] Cycling Commute Survey
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'ca0706d3-7376-463a-a70c-6eae19be7a50',
    'Cycling Commute Survey',
    'probabilistic'::dm_question_type,
    'A survey of 300 people asked whether they cycle to work. 120 respondents are under 30, and 60 of these under-30s cycle. 180 respondents are 30 or older, and 36 of these cycle. One respondent is chosen at random from those who cycle.

What is the probability they are under 30?',
    NULL,
    NULL,
    'B',
    'Total cyclists = 60 + 36 = 96. Under-30 cyclists = 60. P(under 30 | cycles) = 60 / 96 = 5/8.',
    124,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', '1/5', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', '5/8', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', '1/2', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', '8/25', NULL, 4, NULL
  );

  -- [125] Sterile Instruments
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '15606c8f-bf2b-482b-9c95-54476b6addaf',
    'Sterile Instruments',
    'syllogism'::dm_question_type,
    'All surgical instruments are sterile unless they are in the pre-wash bin. No disposable instrument is placed in the pre-wash bin. Some instruments in the pre-wash bin are reusable. All reusable instruments need annual inspection.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    125,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'All disposable instruments are sterile.', 'Yes', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'No instrument in the pre-wash bin is sterile.', 'Yes', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'At least one instrument in the pre-wash bin needs annual inspection.', 'Yes', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'All instruments that need annual inspection are reusable.', 'No', 4
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Every reusable instrument is in the pre-wash bin.', 'No', 5
  );

  -- [126] Parcel Handling Tags
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '277bb4f3-93e7-48bc-ad94-1fbfc9571bcb',
    'Parcel Handling Tags',
    'venn_diagram'::dm_question_type,
    'A delivery company tracks 120 parcels by the handling tags applied. 40 parcels are tagged fragile, 35 heavy, 30 dimensional, 25 return-to-sender. Some parcels have both fragile and heavy tags; some have both heavy and dimensional; some have both dimensional and return-to-sender. No other tag combinations occur. 12 parcels are tagged fragile and heavy, 10 are tagged heavy and dimensional, 8 are tagged dimensional and return-to-sender. 20 parcels have no handling tag.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'A',
    'Freebies: the three stated pair totals are 12 (fragile-heavy), 10 (heavy-dimensional) and 8 (dimensional-return), and 20 parcels have no tag. Scan — B shows 16 in the fragile-heavy overlap, not 12 — eliminate B. C shows 24 outside, not 20 — eliminate C. That leaves A and D. The stem says heavy-and-dimensional = 10; D shows 14 — eliminate D. Answer: A.',
    126,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

