  -- [128] Museum Artefact Inventory
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '5c79147b-a33b-44af-944d-35e658a4f8c9',
    'Museum Artefact Inventory',
    'venn_diagram'::dm_question_type,
    'A museum catalogues 60 newly acquired artefacts. 40 have been inspected. 25 of the inspected artefacts have been photographed. 12 of the photographed artefacts have also been published online. Every photographed artefact was first inspected, and every online-published artefact was first photographed.

Which of the following diagrams is consistent with the data?',
    NULL,
    NULL,
    'A',
    'The premises nest the three categories: online is inside photographed is inside inspected. Outside = 60 − 40 = 20. Inspected-only ring = 40 − 25 = 15. Photographed-only ring (inspected and photographed but not online) = 25 − 12 = 13. Online (innermost) = 12. Scan — B shows 15 in the innermost region (online should be 12) — eliminate. C has 12 in the outermost ring and 15 in the innermost — the two are swapped. D shows 17 outside — but 60 − 40 = 20 must sit outside — eliminate. Answer: A.',
    128,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

