    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', '', '{"diagramLayout":"auto","sets":[{"id":"set1","label":"Inspected","shape":"vertical_oval"},{"id":"set2","label":"Photographed","shape":"circle"},{"id":"set3","label":"Online","shape":"diamond"}],"regions":{"set1_only":15,"set1_set2":13,"set1_set2_set3":12,"outside":20}}'::jsonb, 1, '{"canvas":{"width":300,"height":387},"shapes":[{"id":"set1","label":"Inspected","kind":"ellipse","cx":150.0007247987123,"cy":193.5,"rx":109.3224491764799,"ry":168.18838334843062},{"id":"set2","label":"Photographed","kind":"circle","cx":98.25045299919519,"cy":193.5,"r":86.25045299919519},{"id":"set3","label":"Online","kind":"polygon","points":[[201.25094183348764,107.25099659822939],[288,192.99994523525825],[202.25105136297114,279.7490034017706],[115.50199319645878,194.00005476474175]]}],"labels":[{"region":"set1_only","text":"15","x":160.92765137086104,"y":311.4315230228793,"fontSize":16},{"region":"set1_set2","text":"13","x":90.36720695949926,"y":153.97197497465277,"fontSize":16},{"region":"set1_set2_set3","text":"12","x":155.9310436663406,"y":194.01833239160982,"fontSize":16},{"region":"outside","text":"20","x":19.700000000000003,"y":19,"fontSize":14}],"ambiguity":{"hasDuplicates":false,"allIdentical":false}}'::jsonb
