  -- [129] Four-day Working Week
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'f8761f71-79c0-4a27-8bb4-7e5ddad0e3fa',
    'Four-day Working Week',
    'recognising_assumptions'::dm_question_type,
    'Should companies be required to offer all employees a four-day working week to improve employee mental health?',
    NULL,
    NULL,
    'B',
    'B connects the action (four-day working week) to the outcome (mental health) with a measured 33% reduction in burnout symptoms from a 2023 Icelandic trial. A is preference-based, not a mental-health claim. C addresses operational workload, not mental health. D deflects by raising other causes of mental-health issues, rather than assessing whether the policy itself would help.',
    129,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; many employees would welcome more time off.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; a 2023 Icelandic trial reported a 33% reduction in burnout symptoms among staff switched to a four-day week, with no loss of productivity, directly improving measured mental-health scores.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; small businesses would struggle to cover the same workload in fewer days.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; mental-health issues can also be caused by home life, not just working hours.', NULL, 4, NULL
  );

  -- [130] Warm-up Illusion
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '867cd55a-2f12-4ed9-976e-f1ab93f11e50',
    'Warm-up Illusion',
    'interpreting_info'::dm_question_type,
    'A medical journal article discusses the ''warm-up illusion'' — a theory that athletes perceive themselves as faster after a structured warm-up, even when their measured sprint times are unchanged. Supporters of the theory cite small-scale surveys in which athletes rated themselves as quicker after warming up, although some independent trials have produced mixed results. Critics argue that the self-reported feeling of readiness is more relevant to competition performance than any measured change.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    130,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'After a structured warm-up, athletes'' measured sprint times are definitely unchanged.', 'No', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Critics of the theory consider athletes'' self-reported feeling of readiness to be relevant to performance.', 'Yes', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'A structured warm-up causes athletes to feel faster.', 'No', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Some independent trials of the warm-up illusion produced different results from the small-scale surveys.', 'Yes', 4
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'The warm-up illusion has no effect on sprint performance.', 'No', 5
  );

  -- [131] Whale Song Passage
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'a28dd79b-3b55-4f21-be9f-5e7779f35ac7',
    'Whale Song Passage',
    'interpreting_info'::dm_question_type,
    'Marine biologists have long studied how whale song changes over time. In many populations, all males in a given ocean basin sing nearly identical songs, which are updated gradually over several years. Occasionally a song from a neighbouring basin replaces the resident song across the entire population within a single breeding season — a phenomenon sometimes called a ''cultural revolution''. Most of the observations of this rapid replacement come from a single well-studied population off eastern Australia. While some researchers argue the pattern reflects rapid social learning, others caution that it may not generalise to all cetacean species.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    131,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'In all whale populations, males sing nearly identical songs.', 'No', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Rapid song replacement has been observed off eastern Australia.', 'Yes', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Rapid social learning has been proven to be the mechanism behind these song changes.', 'No', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'All cetacean species undergo rapid song replacement.', 'No', 4
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Whale song is updated more rapidly during a cultural revolution than under normal change.', 'Yes', 5
  );

  -- [132] Morning Shift Deliveries
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '4c590805-52f7-4884-822f-2be8e88302e4',
    'Morning Shift Deliveries',
    'venn_diagram'::dm_question_type,
    'A courier logs 94 deliveries one day. 42 are classed as priority, 35 are oversized, 30 fall within the morning shift window.

14 deliveries are both priority and oversized. 12 priority deliveries fall within the morning shift window. 10 oversized deliveries fall within the morning shift window. 6 deliveries are all three. 17 deliveries are none of these three.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'C',
    'Freebies: 6 deliveries are in all three and 17 are outside. Scan — A shows 4 in the centre — eliminate A. B shows 22 outside — eliminate B. That leaves C and D. The stem says 14 are priority and oversized, and 6 of those are also morning shift, so priority-and-oversized only = 14 − 6 = 8. C shows 8 ✓. D shows 12 — eliminate D. Answer: C.',
    132,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

