  -- [133] Research Wing Access
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '58647de3-9fd7-40dc-9ea9-4447a3c4e8e4',
    'Research Wing Access',
    'syllogism'::dm_question_type,
    'A security badge permits entry to the research wing unless it has been deactivated. Every deactivated badge is logged in the visitor system. Only staff members are issued permanent badges. Badges that are not permanent expire within 24 hours.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    133,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
