  -- [134] Eight-Sided Spinner
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '557c0956-1263-44e8-8893-9cea39e96905',
    'Eight-Sided Spinner',
    'probabilistic'::dm_question_type,
    'A spinner has 8 equal segments numbered 1 to 8. It is spun twice, and each spin is independent of the other.

Given that the first spin lands on an even number, what is the probability that the second spin lands on a number greater than 6?',
    NULL,
    NULL,
    'A',
    'The two spins are independent, so the outcome of the first does not change the probability of the second. Numbers greater than 6 on the spinner are 7 and 8 — that is 2 out of 8 segments, so P(second > 6) = 2/8 = 1/4.',
    134,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

