  -- [138] Zorlins and Flimpets
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '15eec022-ec62-4e3f-9357-5f114af5e48b',
    'Zorlins and Flimpets',
    'syllogism'::dm_question_type,
    'If a zorlin is ripe, it is sweet. Every flimpet is sweet. Some flimpets are zorlins. All unripe zorlins are bitter.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    138,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Every ripe zorlin is sweet.', 'Yes', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Every zorlin is either sweet or bitter.', 'Yes', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'All flimpets are zorlins.', 'No', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Some sweet things are flimpets.', 'Yes', 4
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Every bitter zorlin is a flimpet.', 'No', 5
  );

  -- [139] Longer Lunch Break
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'e8f93408-4b64-4b5a-83ae-bfde0d082900',
    'Longer Lunch Break',
    'recognising_assumptions'::dm_question_type,
    'Should office employees be given a one-hour lunch break, up from thirty minutes, to increase afternoon productivity?',
    NULL,
    NULL,
    'A',
    'A directly connects the longer break (the action) to afternoon productivity (the outcome) with a controlled trial — evidence-based and addressing both parts. B addresses worker happiness, a different outcome. C is a comparative deflection that does not argue against the productivity claim. D addresses working-hours policy generally rather than the action on the table.',
    139,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; a controlled trial at a similar-sized office found afternoon output rose by 8% when employees switched from a 30-minute to a 60-minute lunch break.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; workers who feel rested during the day are happier at work.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; early finishing times tend to improve afternoon productivity more than longer lunch breaks do.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; lengthening the lunch break would push the contracted working day out by thirty minutes for every employee.', NULL, 4, NULL
  );

