  -- [143] Rare Nut Allergy Test
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '4f95045e-40db-4b34-904f-0b4ea7b12f43',
    'Rare Nut Allergy Test',
    'probabilistic'::dm_question_type,
    'A rare nut allergy affects 1 in 500 people. A new skin-prick test correctly identifies 99% of true cases as positive (when the allergy is present) and correctly identifies 97% of non-cases as negative (when the allergy is absent). A randomly selected person tests positive.

Approximately what is the probability that this person actually has the allergy?',
    NULL,
    NULL,
    'B',
    'Imagine 100,000 people. About 200 have the allergy and 99,800 do not. True positives = 99% × 200 = 198. False positives = 3% × 99,800 = 2,994. Total positives ≈ 198 + 2,994 = 3,192. P(allergy | positive) ≈ 198 / 3,192 ≈ 6.2%. Option A (3%) matches the false-positive rate rather than the conditional probability. Option C (50%) is a naive assumption. Option D (99%) confuses the test''s sensitivity with the chance of having the allergy.',
    143,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'About 3%', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'About 6%', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'About 50%', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'About 99%', NULL, 4, NULL
  );

