  -- [145] Prescription Charges for Over-60s
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '34903a69-3f0a-4784-8306-f7135d92449b',
    'Prescription Charges for Over-60s',
    'recognising_assumptions'::dm_question_type,
    'Should NHS prescription charges be abolished for all adults over the age of 60 to improve long-term health outcomes in this age group?',
    NULL,
    NULL,
    'B',
    'B links the action (abolishing charges for over-60s) to the outcome (improved long-term health) with comparative health-economics evidence. A is anecdotal and does not address outcomes. C is a comparative deflection that never evaluates whether the proposed action would still help. D addresses NHS funding, not health outcomes for the over-60 group.',
    145,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; pharmacists report that older patients frequently ask for cheaper alternatives to prescribed medicines.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; a 2024 health-economics study found that in OECD countries where prescription charges were abolished for over-60s, hospital admissions in that age group fell by 12%, directly improving long-term health outcomes.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; adults over 60 are not the age group with the poorest long-term health outcomes in the UK.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; abolishing charges would reduce NHS funding available for other essential services.', NULL, 4, NULL
  );

  -- [146] Blood-Pressure Monitor Comparison
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '1b645a71-0bcc-4964-9fd7-f15371520e61',
    'Blood-Pressure Monitor Comparison',
    'probabilistic'::dm_question_type,
    'Two home blood-pressure monitors are tested. Monitor X gives readings within ±2 mmHg of the true value in 88 of 100 patients. Monitor Y gives readings within ±2 mmHg of the true value in 94 of 100 patients. When each monitor is used to re-test the same patient ten times, Monitor X produces the same reading on 8 occasions and Monitor Y produces the same reading on 5 occasions.

Which statement best compares the two monitors?',
    NULL,
    NULL,
    'B',
    'Accuracy is how often the reading is correct: X = 88%, Y = 94% — Y is more accurate. Precision is how consistent repeated readings are: X = 8/10 = 80%, Y = 5/10 = 50% — X is more precise. So Y is more accurate but X is more precise.',
    146,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Monitor X is more accurate but Monitor Y is more precise.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Monitor Y is more accurate but Monitor X is more precise.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Monitor Y is both more accurate and more precise.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Monitor X is both more accurate and more precise.', NULL, 4, NULL
  );

  -- [147] Sibling Ages
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '799f526c-22e5-423b-a110-517031c350e6',
    'Sibling Ages',
    'logic_puzzle'::dm_question_type,
    'Four siblings — Alex, Ben, Cora and Dina — have a combined age of 81 years. Alex is three years younger than Ben. Cora is twice Dina''s age. Dina is four years younger than Alex.

How old is Dina?',
    NULL,
    NULL,
    'B',
    'Let Dina = D. Then Alex = D + 4, Ben = Alex + 3 = D + 7, Cora = 2D. Sum: D + (D + 4) + (D + 7) + 2D = 5D + 11 = 81, so 5D = 70 and D = 14.',
    147,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

