  -- [148] Loud Fireworks Ban
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '77023809-710f-4817-bc9a-9c7f1995b958',
    'Loud Fireworks Ban',
    'recognising_assumptions'::dm_question_type,
    'Should the UK ban the retail sale of loud (above 80 dB) fireworks to the general public to reduce noise-related distress among pets and farm animals?',
    NULL,
    NULL,
    'A',
    'A links the action (ban on loud retail fireworks) to the outcome (animal distress) with evidence from similar bans abroad. B addresses human injuries, not animal distress. C observes that distress would not be fully eliminated, but reducing distress doesn''t require eliminating every source. D addresses cultural importance, not the outcome.',
    148,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; a government-commissioned RSPCA report found that bans on loud retail fireworks in three comparable European countries reduced recorded pet distress incidents on fireworks nights by around 70%.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; fireworks are dangerous and many people injure themselves with them each year.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; large professional displays would still produce enough noise to cause animal distress.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; fireworks are an important part of British cultural celebrations.', NULL, 4, NULL
  );

