  -- [156] Emergency Department Waits
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'f80b1d19-32b7-4c62-a0a0-88e18a4a9659',
    'Emergency Department Waits',
    'interpreting_info'::dm_question_type,
    'The table shows the median wait time (in minutes) for patients arriving at the emergency departments of three hospitals, split by triage category, in one week of March 2024.',
    '{"headers":["Hospital","Immediate","Urgent","Standard","Non-urgent"],"rows":[["Royal Oak","3","28","95","180"],["St Bede''s","4","35","110","210"],["Westbrook","2","24","80","155"]]}'::jsonb,
    NULL,
    '[object Object]',
    NULL,
    156,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Westbrook had the shortest median wait time in every triage category shown.', 'Yes', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'St Bede''s median non-urgent wait was more than twice its median urgent wait.', 'Yes', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Westbrook treats a higher proportion of non-urgent patients than the other hospitals.', 'No', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Every hospital''s median immediate wait was under 5 minutes in the week shown.', 'Yes', 4
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Immediate patients at all three hospitals will wait under 5 minutes in 2025.', 'No', 5
  );

  -- [157] Sixth-Form Subjects
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'ebf2b357-59b7-4e8f-bbc7-1814075b951f',
    'Sixth-Form Subjects',
    'probabilistic'::dm_question_type,
    'A school has 80 sixth-formers. 45 study Maths, 30 study Physics, and 20 study both Maths and Physics. A sixth-former is picked at random from those studying Maths.

What is the probability that the chosen student also studies Physics?',
    NULL,
    NULL,
    'B',
    'Conditional probability: the denominator is the Maths group (45), not the whole year (80). Students who study both = 20. P(Physics | Maths) = 20 / 45 = 4/9.',
    157,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', '1/4', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', '4/9', NULL, 2, NULL
  );
