  -- [158] Hospital Surgeons
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'c4c835da-58f5-4901-bda6-bd9c9e61cb3f',
    'Hospital Surgeons',
    'syllogism'::dm_question_type,
    'All senior surgeons at the hospital trained in London. Some surgeons at the hospital are senior. Most surgeons who trained in London studied at King''s College. No junior surgeon leads a transplant team.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    158,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'All senior surgeons at the hospital studied at King''s College.', 'No', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'At least some surgeons at the hospital trained in London.', 'Yes', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'No senior surgeon leads a transplant team.', 'No', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Every surgeon who leads a transplant team must be a senior surgeon.', 'No', 4
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'A junior surgeon does not lead a transplant team.', 'Yes', 5
  );

