  -- [160] At Least One Spade in Three Draws
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '9b22f952-ba16-4124-8d6f-23d1729fcc20',
    'At Least One Spade in Three Draws',
    'probabilistic'::dm_question_type,
    'A card is drawn at random from a standard 52-card deck and then replaced. This is done three times independently.

What is the probability of drawing at least one spade across the three draws?',
    NULL,
    NULL,
    'C',
    'Use the complement. P(not a spade on one draw) = 39/52 = 3/4. P(no spade in three independent draws) = (3/4)^3 = 27/64. P(at least one spade) = 1 − 27/64 = 37/64.',
    160,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', '3/4', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', '27/64', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', '37/64', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', '1/4', NULL, 4, NULL
  );

  -- [161] Mandatory First Aid Training
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'f382afc9-502c-4dcd-8fd6-12f9bd93b212',
    'Mandatory First Aid Training',
    'recognising_assumptions'::dm_question_type,
    'Should workplace first aid training be made mandatory for all UK employees to reduce the severity of workplace injuries?',
    NULL,
    NULL,
    'B',
    'B links the action (mandatory training) to the outcome (reduced injury severity) with specific HSE evidence. A addresses employee confidence, not injury severity. C focuses on a narrow subgroup ("some industries") rather than the broad population. D addresses productivity, not injury severity.',
    161,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; many employees report feeling more confident at work after completing first aid training.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; a 2023 HSE analysis of UK workplaces found that sites with trained first aiders saw 30% fewer injuries escalate to hospital admission, directly reducing injury severity.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; some industries rarely see serious workplace injuries, making the training redundant for those workers.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; mandatory training would take time away from productive work tasks for every employee.', NULL, 4, NULL
  );

  -- [162] Free NHS Staff Parking
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '2c0e0973-cb35-44b7-b773-26e34589c9ff',
    'Free NHS Staff Parking',
    'recognising_assumptions'::dm_question_type,
    'Should the NHS provide free parking at all English hospitals for staff on shift to reduce staff attrition?',
    NULL,
    NULL,
    'B',
    'B links the action (free staff parking) to the outcome (staff attrition) with a 34-trust internal survey. A is emotional and does not address attrition. C restricts the scope to public-transport users and ignores the attrition outcome. D raises cost allocation rather than the staff retention effect.',
    162,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; hospital staff work long and unsocial hours.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; a 2022 NHS workforce survey of 34 trusts showed that trusts offering free staff parking had 17% lower 12-month attrition among front-line staff than trusts that charged for parking.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; some staff use public transport and would not benefit from free parking.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; funding the scheme would divert money from direct patient care.', NULL, 4, NULL
  );

  -- [163] Shelf Arrangement
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '85d2adfc-b685-4d1d-8b2c-aa6347f12bc6',
    'Shelf Arrangement',
    'logic_puzzle'::dm_question_type,
    'Five books (Atlas, Biology, Cooking, Dictionary, Encyclopedia) are arranged left to right on a shelf. The Dictionary is somewhere to the right of the Atlas. The Biology is immediately next to the Cooking. The Encyclopedia is at one of the ends. The Atlas is not at either end.

Which of the following arrangements, from left to right, is consistent with all the constraints?',
    NULL,
    NULL,
    'C',
    'The Atlas must be in position 2, 3, or 4. The Encyclopedia must be at position 1 or 5. The Dictionary must be right of the Atlas, and Biology–Cooking must be adjacent. Option A has Atlas at position 1 — fails. Option B has the Dictionary to the left of the Atlas — fails. Option D has the Encyclopedia in the middle — fails. Option C places Encyclopedia at position 1, Atlas at 2, Biology at 3, Cooking at 4, Dictionary at 5; every constraint holds.',
    163,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Atlas, Biology, Cooking, Dictionary, Encyclopedia', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Dictionary, Atlas, Biology, Cooking, Encyclopedia', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Encyclopedia, Atlas, Biology, Cooking, Dictionary', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Biology, Cooking, Encyclopedia, Atlas, Dictionary', NULL, 4, NULL
  );

  -- [164] 20 mph Residential Limit
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '135b0433-b491-4cec-87ea-c11e7b5e534e',
    '20 mph Residential Limit',
    'recognising_assumptions'::dm_question_type,
    'Should the UK government introduce a nationwide 20 mph speed limit on all residential streets to reduce child pedestrian injuries?',
    NULL,
    NULL,
    'B',
    'B links the action (20 mph limit) to the outcome (child pedestrian injuries) with a published injury-rate figure. A addresses driver perception, not injuries. C narrows the scope to quiet cul-de-sacs, ignoring residential streets more broadly. D is opinion-based and does not address injury outcomes.',
    164,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; drivers already find 30 mph limits too fast in school zones.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; published Transport Research Laboratory data show child pedestrian injury rates fall by 41% on streets where the default limit moves from 30 mph to 20 mph.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; residents in quiet cul-de-sacs rarely see child pedestrians near traffic.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; some motorists would resent the change.', NULL, 4, NULL
  );

  -- [165] Plastic Cutlery Ban
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '43155dbf-a375-49ee-8e3c-cc3a59364afa',
    'Plastic Cutlery Ban',
    'recognising_assumptions'::dm_question_type,
    'Should single-use plastic cutlery be banned nationwide to reduce marine plastic pollution?',
    NULL,
    NULL,
    'A',
    'A connects the action (ban) to the outcome (marine pollution) with evidence that cutlery is a significant source. B addresses preference, not pollution. C addresses business cost, not pollution. D deflects by comparing sources but does not address whether banning cutlery would still reduce pollution.',
    165,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; a recent beach survey found plastic cutlery in the top five items recovered from UK coastlines, and a national ban would remove this source of marine litter.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; plastic cutlery is unpleasant to use compared with wooden alternatives.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; many small takeaways rely on plastic cutlery and would find replacements expensive.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; most marine plastic pollution comes from fishing gear, not cutlery.', NULL, 4, NULL
  );

