  -- [167] E-Scooter Pavement Ban
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'd2b525f5-15cf-4989-b8d4-c653cdecf2b5',
    'E-Scooter Pavement Ban',
    'recognising_assumptions'::dm_question_type,
    'Should e-scooters be banned from city centre pavements to improve pedestrian safety?',
    NULL,
    NULL,
    'A',
    'A links the action (pavement ban) to the outcome (pedestrian safety) with transport authority evidence. B is opinion-based and does not address safety. C addresses rider welfare, not pedestrian safety. D deflects by comparing sources but does not address whether the ban would still help.',
    167,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; transport authority data from five UK cities showed pedestrian injuries fell by 42% after pavement e-scooter bans, directly improving pedestrian safety.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; many pedestrians report feeling uncomfortable sharing pavements with e-scooters.', NULL, 2, NULL
