  -- [171] Mandatory Flu Vaccinations
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'a30e127b-01bc-4ebb-8129-a94857efd20e',
    'Mandatory Flu Vaccinations',
    'recognising_assumptions'::dm_question_type,
    'Should all hospital staff be required to receive annual flu vaccinations to reduce patient infection rates?',
    NULL,
    NULL,
    'A',
    'A is the strongest argument: it links the action (mandatory staff vaccination) to the outcome (patient infection rates) with trial data showing the intended effect. B addresses staff attitudes, not infection rates. C addresses staff autonomy, not the proposition''s outcome. D uses ''some'' and addresses staff availability, not patient infections.',
    171,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; a trial across three UK teaching hospitals found that wards with over 90 per cent staff vaccination recorded 35 per cent fewer patient flu cases than wards below 70 per cent.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; most nurses already feel morally obliged to protect their patients.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; mandating vaccinations removes individual staff choice.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; some staff experience side effects that limit their working availability.', NULL, 4, NULL
  );

  -- [172] Luggage Scanner Comparison
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '1eef2cc5-e0d2-4f6d-9b11-d3d9833cf081',
    'Luggage Scanner Comparison',
    'probabilistic'::dm_question_type,
    'Two luggage scanners are tested at an airport. When a scanner is shown a bag containing a prohibited item, Scanner X correctly flags it 91 times out of 100 and Scanner Y correctly flags it 78 times out of 100. When the same bag is scanned 60 times in a row by each machine, Scanner X returns the same result 54 times and Scanner Y returns the same result 58 times.

Which statement best compares the two scanners?',
    NULL,
    NULL,
    'B',
    'Accuracy is how often the machine gives the correct result. Scanner X = 91/100 = 91%, Scanner Y = 78/100 = 78% — Scanner X is more accurate. Precision is how consistently the machine gives the same result. Scanner X = 54/60 ≈ 90%, Scanner Y = 58/60 ≈ 97% — Scanner Y is more precise.',
    172,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Scanner X is both more accurate and more precise.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Scanner X is more accurate but Scanner Y is more precise.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Scanner Y is both more accurate and more precise.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Scanner X is more precise but Scanner Y is more accurate.', NULL, 4, NULL
  );

