  -- [175] Library Book Tags
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '4c4b2dd1-2f70-4797-bf6a-03c528e3e949',
    'Library Book Tags',
    'venn_diagram'::dm_question_type,
    'A library records 120 recently loaned books categorised by three tags. 54 are fiction, 40 are hardback, and 35 are bestsellers. 18 are both fiction and hardback. 14 are both fiction and bestseller. 12 are both hardback and bestseller. 8 books fall into all three categories. 27 books fall into none of these categories.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'A',
    'Two freebies: 8 books are in all three categories (the centre) and 27 books fall outside all three. Scan — B shows 6 in the centre, not 8 — eliminate B. C shows 31 outside, not 27 — eliminate C. That leaves A and D. The stem says 18 are both fiction and hardback; 8 of those are also bestsellers, so fiction-and-hardback only = 18 − 8 = 10. A shows 10 there ✓. D shows 6 there — eliminate D. Answer: A.',
    175,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
