  -- [176] Vaping in Cars with Children
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '70d304da-b0ca-4765-8a18-d10d28e6b22f',
    'Vaping in Cars with Children',
    'recognising_assumptions'::dm_question_type,
    'Should vaping in cars carrying passengers under 18 be made illegal to reduce childhood asthma rates?',
    NULL,
    NULL,
    'B',
    'B directly connects the action (banning in-car vaping around under-18s) to the outcome (childhood asthma) with a specific NHS study. A uses ''many'' and addresses parental choice rather than asthma. C raises enforcement difficulty without engaging with asthma. D is a comparative argument that sidesteps the asthma outcome entirely.',
    176,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; many parents already choose not to vape in front of their children.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; a 2023 NHS study found that second-hand vapour exposure in enclosed vehicles increases the risk of new-onset childhood asthma by 34%, so banning in-car vaping where children are present directly reduces asthma cases.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; the law would be difficult for police to enforce.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; vaping produces less harmful residue than tobacco smoke.', NULL, 4, NULL
  );

  -- [177] Round Table Seats
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'cca1d657-18b6-4e67-ba59-ddf0887afe6d',
    'Round Table Seats',
    'logic_puzzle'::dm_question_type,
    'Six friends — Ava, Bao, Cal, Dev, Eve, Fin — sit around a round table at six numbered seats 1–6 arranged clockwise. Ava sits at seat 1. Bao sits directly opposite Ava. Cal sits two seats clockwise from Bao. Dev sits immediately to Ava''s right (clockwise). Eve sits directly opposite Dev.

Who sits at seat 6?',
    NULL,
    NULL,
    'C',
    'Opposite pairs at a six-seat round table are 1–4, 2–5, and 3–6. Ava at 1 puts Bao at 4. Two seats clockwise from Bao (4) is seat 6, so Cal is at 6. Dev immediately to Ava''s right (clockwise from 1) is at seat 2. Eve directly opposite Dev (2) is at seat 5. Fin takes the remaining seat 3. Seat 6 is Cal.',
    177,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Dev', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Fin', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Cal', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Eve', NULL, 4, NULL
  );

  -- [178] Lab Access
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '612db07d-ee12-4f29-8d81-17760b7b25d6',
    'Lab Access',
    'syllogism'::dm_question_type,
    'A key card cannot unlock the laboratory unless it has been registered this month. Every key card registered this month shows a green indicator light. Only senior staff may register more than one key card. No visitor is senior staff.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    178,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Every key card that can unlock the laboratory shows a green indicator light.', 'Yes', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'If a key card shows a green indicator light, it must have been registered this month.', 'No', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'No visitor may register more than one key card.', 'Yes', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
