  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'If a key card has not been registered this month, it cannot unlock the laboratory.', 'Yes', 5
  );

  -- [179] Airport 100 ml Liquid Limit
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'debea59f-1dec-4f14-8a62-5f9a855b5789',
    'Airport 100 ml Liquid Limit',
    'recognising_assumptions'::dm_question_type,
    'Should the UK remove the 100 ml liquid limit at airport security to reduce average passenger queue times?',
    NULL,
    NULL,
    'B',
    'B directly links the action (removing the 100 ml limit) to the outcome (queue times) with measured results from three UK airports. A is emotional rather than addressing queues. C restates a constraint rather than arguing against the change''s queue effect. D raises historical justification unrelated to queue times.',
    179,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; travellers dislike having to throw away water bottles at security.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; three UK airports that trialled removing the 100 ml limit after installing CT scanners reported average queue times fell by 43% over six months.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; security officers must still screen liquids in some way even without the limit.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; the 100 ml rule was introduced in response to past terror threats involving liquid explosives.', NULL, 4, NULL
  );

  -- [180] Biased Coins
