    'Biased Coins',
    'probabilistic'::dm_question_type,
    'A biased coin lands on heads with probability 0.6 on each toss, independently of previous tosses. The coin is tossed three times.

What is the probability of getting exactly two heads in the three tosses?',
    NULL,
    NULL,
    'B',
    'There are three sequences with exactly two heads (HHT, HTH, THH). Each has probability 0.6 × 0.6 × 0.4 = 0.144. Total probability = 3 × 0.144 = 0.432.',
    180,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
