  -- [200] School Clubs
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '04691da6-b3dd-422b-950e-283594ceabe4',
    'School Clubs',
    'venn_diagram'::dm_question_type,
    'A school surveys 90 pupils about three after-school clubs. 28 attend debate, 30 attend drama, 26 attend coding. 14 pupils attend both debate and drama. No pupil attends both coding and debate. No pupil attends both coding and drama. 20 pupils attend none of these three clubs.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'B',
    'Freebies: 20 pupils are outside all three and 14 attend both debate and drama. Scan — A shows 22 outside, not 20 — eliminate A. C shows 16 outside, not 20 — eliminate C. That leaves B and D. The stem says 14 attend both debate and drama; D shows 10 in that overlap — eliminate D. B matches every stated overlap and the none count. Answer: B.',
    200,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
