  -- [202] Single-Use Coffee Cup Ban
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '5813cd78-68ab-4943-8c8b-654b8c9028bd',
    'Single-Use Coffee Cup Ban',
    'recognising_assumptions'::dm_question_type,
    'Should single-use coffee cups be banned in UK cafés to reduce landfill waste?',
    NULL,
    NULL,
    'A',
    'A links the action (banning single-use coffee cups) directly to the outcome (reducing landfill waste) with specific evidence. B is opinion-based and does not address landfill waste. C addresses café operating costs, not landfill. D restates general concerns without evidence and does not justify keeping the cups. A is the strongest.',
    202,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; Environment Agency audits estimate that single-use coffee cups account for roughly 2.5 billion items reaching UK landfill annually, and switching cafés to reusable cups would eliminate this stream directly.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; many customers say ceramic cups feel nicer to drink from.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; some small cafés would struggle with the washing-up costs and staffing needed for reusable cups.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; the government should focus on bigger sources of landfill rather than coffee cups.', NULL, 4, NULL
  );

  -- [203] Gyms and GP Visits
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'adfbd30a-8e47-4ae2-a52e-2a7391ddfeb6',
    'Gyms and GP Visits',
    'interpreting_info'::dm_question_type,
    'A regional health report notes that in districts with a larger number of community gyms, residents record fewer GP visits for back-pain complaints. A health commentator argues that if every district built more gyms, GP back-pain visits would fall nationwide. The report itself states only that the two figures correlate and does not assess any causal mechanism.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    203,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'In districts with more community gyms, fewer GP back-pain visits are recorded.', 'Yes', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Building more community gyms in a district will reduce GP back-pain visits in that district.', 'No', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'The regional health report identifies a causal mechanism.', 'No', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'GP back-pain visits are falling in every district in the region.', 'No', 4
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Some districts in the region have community gyms.', 'Yes', 5
  );

  -- [204] Two Hearts in a Row
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '6ea94265-f6a8-40fe-86bf-fce5945213fc',
    'Two Hearts in a Row',
    'probabilistic'::dm_question_type,
    'A standard 52-card deck has four suits (spades, hearts, diamonds, clubs) of 13 cards each. Two cards are drawn in succession from a shuffled deck, without replacement.

What is the probability that both cards are hearts?',
    NULL,
    NULL,
    'C',
    'P(first heart) = 13/52 = 1/4. After one heart is removed, 12 hearts remain in 51 cards, so P(second heart | first heart) = 12/51 = 4/17. P(both hearts) = (1/4) × (4/17) = 4/68 = 1/17.',
    204,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', '1/4', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', '1/16', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
