  -- [206] Market Research Interests
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '48b75209-a0c4-473e-926a-51201242c1eb',
    'Market Research Interests',
    'venn_diagram'::dm_question_type,
    'A market research firm interviews 140 respondents and records four product interests. 42 are interested in podcasts, 30 in audiobooks, 36 in yoga apps, and 28 in running trackers. 14 respondents are interested in both podcasts and audiobooks. 12 respondents are interested in both yoga apps and running trackers. No respondent who is interested in podcasts or audiobooks is also interested in yoga apps or running trackers. 30 respondents are interested in none of these four categories.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'A',
    'Two freebies from the stem: 14 respondents are interested in both podcasts and audiobooks, and 12 are interested in both yoga apps and running trackers. Scan — B shows 12 in the podcast-and-audiobook overlap and 14 in the yoga-and-running overlap (the two numbers swapped) — eliminate B. C shows 18 and 16 in the two overlaps, neither matches — eliminate C. D shows 16 and 14 in the overlaps — eliminate D. A shows 14 and 12 in the two overlaps. Answer: A.',
    206,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
