  -- [218] Two Packing Machines
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'ae4eaf27-1649-4baf-9202-1d65ff746aae',
    'Two Packing Machines',
    'probabilistic'::dm_question_type,
    'A factory has two independent packing machines. Machine A produces a defective packet with probability 0.05. Machine B produces a defective packet with probability 0.08. A supervisor picks one packet at random from Machine A and one packet at random from Machine B.

What is the probability that at least one of the two packets is defective?',
    NULL,
    NULL,
    'B',
    'P(A not defective) = 0.95 and P(B not defective) = 0.92. Independence gives P(neither defective) = 0.95 × 0.92 = 0.874. So P(at least one defective) = 1 − 0.874 = 0.126. Option A (0.004) is P(both defective). Option C (0.130) is 0.05 + 0.08, which over-counts the case where both are defective. Option D (0.874) is P(neither defective).',
    218,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
