  -- [222] Free Bus Travel for Under-18s
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'e5e539d1-f545-4aac-b6fb-d7ce78aae71e',
    'Free Bus Travel for Under-18s',
    'recognising_assumptions'::dm_question_type,
    'Should free bus travel be introduced for all under-18s in the UK to reduce the number of family car journeys?',
    NULL,
    NULL,
    'B',
    'B connects the action (free under-18 bus travel) to the outcome (fewer family car journeys) with pilot evidence showing the intended effect. A addresses fare affordability, not car journeys. C is a sweeping claim about geography. D is about bus emissions, a different outcome. B is strongest.',
    222,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; teenagers often don''t have money for bus fares, so paying is a barrier.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; a Department for Transport pilot in Scotland found that offering free bus travel to under-22s cut car-based school runs by around 18%, so a UK-wide scheme is likely to produce a similar reduction.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; many families live too far from bus routes to benefit.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; buses emit carbon, so filling them with schoolchildren still pollutes.', NULL, 4, NULL
  );

  -- [223] Language Exam Passes
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'ce76c780-cf23-4ff9-bb3d-b13c03877931',
    'Language Exam Passes',
    'venn_diagram'::dm_question_type,
    'A language school tests 60 candidates. 20 passed French, 24 passed Spanish, and 16 passed Mandarin. 6 candidates passed both French and Mandarin. 7 passed both Spanish and Mandarin. No candidate passed both French and Spanish. 13 candidates passed none of the three exams.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'A',
    'Freebies: 13 passed none (outside), French-and-Mandarin = 6, and Spanish-and-Mandarin = 7. Scan — B shows 11 outside, eliminate B. C shows 15 outside, eliminate C. D swaps the French-and-Mandarin (7) and Spanish-and-Mandarin (6) counts — eliminate D. A matches all the stated values.',
    223,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

