  -- [224] Dinner Shift Schedule
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'c1ce28d3-fd7a-4263-86fc-5064b0bd4377',
    'Dinner Shift Schedule',
    'logic_puzzle'::dm_question_type,
    'A restaurant manager is scheduling five servers — Fen, Gita, Hari, Ira, Jon — across a five-hour dinner shift that starts at 6 pm. Each server covers exactly one one-hour slot (6 pm, 7 pm, 8 pm, 9 pm, or 10 pm), and no slot has more than one server. Fen covers the 7 pm slot. Gita covers an earlier slot than Ira. Hari covers the slot immediately before Jon. Jon covers the 10 pm slot.

Who covers the 6 pm slot?',
    NULL,
    NULL,
    'B',
    'Jon is at 10 pm and Hari is immediately before him, so Hari is at 9 pm. Fen is at 7 pm, leaving Gita and Ira in the 6 pm and 8 pm slots. Gita is earlier than Ira, so Gita is at 6 pm and Ira is at 8 pm. The 6 pm slot belongs to Gita.',
    224,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Fen', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Gita', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Ira', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Hari', NULL, 4, NULL
  );

  -- [225] Garden Plants
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'f2a4129b-4beb-4ccb-b167-b119f54b0c75',
    'Garden Plants',
    'interpreting_info'::dm_question_type,
    'In a garden, every rose bush is either white or pink, except for a few rare hybrid bushes that are yellow. All hedge plants are green, and most of the hedge plants are trimmed weekly. Only climbing plants grow above three metres in this garden.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    225,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'A rose bush in the garden that is not pink must be either white or yellow.', 'Yes', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'A plant in the garden that is not a climbing plant cannot grow above three metres.', 'Yes', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
