  -- [231] Truth Teller Trio
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '84909feb-e99c-4ac5-9d9c-5d2a0ade25dc',
    'Truth Teller Trio',
    'logic_puzzle'::dm_question_type,
    'Three colleagues — Anya, Bri and Cal — are each either a truth-teller (always tells the truth) or a liar (always lies). Each makes exactly one statement:

Anya: ''Bri is a liar.''
Bri: ''Cal is a truth-teller.''
Cal: ''Anya and I are both truth-tellers.''

How many of the three are liars?',
    NULL,
    NULL,
    'C',
    'Suppose Cal is a truth-teller. His statement would mean Anya is also a truth-teller. Then Anya''s ''Bri is a liar'' is true, making Bri a liar. But Bri''s ''Cal is a truth-teller'' would be true — a liar cannot say something true. Contradiction. So Cal is a liar. Bri''s claim that Cal is a truth-teller is then false, so Bri is a liar. Anya''s claim that Bri is a liar is true, so Anya is a truth-teller. Two liars: Bri and Cal.',
    231,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', '0', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', '1', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', '2', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', '3', NULL, 4, NULL
  );

