  -- [236] Steering Committee Selection
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'dc68bbff-7318-4d24-920f-7ed97b4e0689',
    'Steering Committee Selection',
    'logic_puzzle'::dm_question_type,
    'A company is forming a five-person steering committee from four departments. Each department contributes people as listed below.

Sales: Rahul (M), Tom (M), Maya (F). Engineering: Ben (M), Lina (F), Priya (F). Finance: Dan (M), Sara (F). HR: Joy (F).

The committee must include at least one person from each department, at most two people from any single department, and exactly three men and two women. Sales and Engineering must together contribute exactly three people. Rahul will not be on the committee.

Who must definitely be on the committee?',
    NULL,
    NULL,
    'C',
    'HR has only Joy, so Joy is on. With Rahul out, Sales can contribute from {Tom, Maya}. If Sales contributes 2, both Tom and Maya are on; the remaining Engineering seat must be male (only Ben fits) and Finance must be male (Dan). If Sales contributes 1 (Tom, since Maya alone would force too many women), Engineering contributes 2 including Ben plus one of Lina/Priya, and Finance is Dan. In every valid configuration Ben is on the committee. Lina and Priya each appear in only one configuration; Sara never appears (Finance is always Dan).',
    236,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Lina', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Maya', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Ben', NULL, 3, NULL
  );
