    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Sara', NULL, 4, NULL
  );

  -- [237] Three Friends, One Liar
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '2709a091-a6f7-4896-a3a5-8d61def512eb',
    'Three Friends, One Liar',
    'logic_puzzle'::dm_question_type,
    'Three friends — Hana, Ishan, and Jade — each make one statement. Exactly one of them is lying; the other two are telling the truth.

Hana says, ''Jade is lying.''
Ishan says, ''I am telling the truth.''
Jade says, ''Ishan is lying.''

Who is lying?',
    NULL,
    NULL,
    'C',
    'Test each case with exactly one liar. If Hana lies, Jade is truthful, so Jade''s claim that Ishan lies is true — two liars, contradiction. If Ishan lies, Hana tells the truth, so Jade lies — again two liars. If Jade lies: Hana''s claim that Jade lies is true, Ishan''s claim that he tells the truth is true, and Jade''s claim that Ishan lies is false. Consistent: only Jade lies.',
    237,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Hana', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Ishan', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
