  -- [240] Coffee Tasting Order
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '007d44ab-7662-42d8-b80c-cf39b4693266',
    'Coffee Tasting Order',
    'logic_puzzle'::dm_question_type,
    'Five samples of coffee — Bolivar, Castro, Dorian, Ember and Faro — are tasted in five rounds (1 to 5). Faro is tasted in round 1. Ember is tasted in round 2. Castro is tasted immediately after Dorian. Bolivar is tasted in a later round than Castro.

Which of the following lists the samples in tasting order from round 1 to round 5?',
    NULL,
    NULL,
    'D',
    'Faro = round 1 and Ember = round 2 are fixed, so rounds 3, 4 and 5 are split between Bolivar, Castro and Dorian. Castro is immediately after Dorian, so they sit at (3, 4) or (4, 5). If Dorian = 4 and Castro = 5, Bolivar would need to be later than 5, which is impossible. So Dorian = 3 and Castro = 4, leaving Bolivar = 5. Order: Faro, Ember, Dorian, Castro, Bolivar.',
    240,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
