  -- [243] Drug Screening Test
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '28e2ab2d-96ee-4982-ac82-04af543ceb68',
    'Drug Screening Test',
    'probabilistic'::dm_question_type,
    'A workplace drug screening test has the following properties. When a worker has used the substance, the test correctly returns positive 96% of the time. When a worker has not used the substance, the test correctly returns negative 88% of the time. In a workforce of 5,000 workers, 250 have actually used the substance. A randomly chosen worker tests positive.

Approximately what is the probability that this worker has actually used the substance?',
    NULL,
    NULL,
    'A',
    'Of 5,000 workers, 250 are users and 4,750 are non-users. True positives = 96% × 250 = 240. False positives = 12% × 4,750 = 570. Total positives = 240 + 570 = 810. Probability of being a user given a positive test = 240 / 810 ≈ 0.296, so about 30%.',
    243,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'About 30%', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'About 5%', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'About 50%', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'About 96%', NULL, 4, NULL
  );

