  -- [250] Detentions Average
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '4748a417-34b7-4746-81b3-8f1f59113672',
    'Detentions Average',
    'logic_puzzle'::dm_question_type,
    'In a class of ten pupils, the average number of detentions per pupil this term is 3.6. Four pupils received three detentions each, three pupils received two detentions each, and one pupil received one detention. Of the remaining two pupils, Aisha received three more detentions than Ben.

How many detentions did Ben receive?',
    NULL,
    NULL,
    'C',
    'Total detentions = 10 × 3.6 = 36. Known detentions = (4 × 3) + (3 × 2) + 1 = 12 + 6 + 1 = 19. Aisha and Ben share 36 − 19 = 17 detentions. Aisha = Ben + 3, so Ben + (Ben + 3) = 17 ⇒ 2 × Ben = 14 ⇒ Ben = 7.',
    250,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', '5', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', '6', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', '7', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', '10', NULL, 4, NULL
  );

