  -- [252] Rare Disease Test
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '9cf1e56a-6b3c-4cae-be0f-819317da2da8',
    'Rare Disease Test',
    'probabilistic'::dm_question_type,
    'A rare disease affects 1 in 2,000 adults. A screening test is 98% sensitive (correctly identifies 98% of people who have the disease) and 95% specific (correctly identifies 95% of people who do not have the disease).

If an adult from this population tests positive, roughly what is the probability they actually have the disease?',
    NULL,
    NULL,
    'A',
    'Imagine 100,000 adults: 50 have the disease, 99,950 do not. True positives ≈ 98% × 50 = 49. False positives = 5% × 99,950 ≈ 4,998. Total positives ≈ 5,047. P(disease | positive) ≈ 49 / 5,047 ≈ 1%. The high test accuracy does not overcome the very low base rate.',
    252,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Around 1%', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Around 25%', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
