  -- [258] At Least One Six
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'a8da9809-857d-43fe-8a08-8ac17bbbec55',
    'At Least One Six',
    'probabilistic'::dm_question_type,
    'A fair six-sided die is rolled three times, and each roll is independent of the others.

What is the probability of getting at least one 6 in the three rolls?',
    NULL,
    NULL,
    'A',
    'Work with the complement: P(no 6 on one roll) = 5/6. P(no 6 in three rolls) = (5/6)^3 = 125/216. P(at least one 6) = 1 − 125/216 = 91/216.',
    258,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

