  -- [261] Screen-Based Homework Cap
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '7fbe3799-c19f-4ad5-8248-4df8e566f341',
    'Screen-Based Homework Cap',
    'recognising_assumptions'::dm_question_type,
    'Should schools cap daily screen-based homework at 30 minutes for primary-school pupils to improve children''s sleep quality?',
    NULL,
    NULL,
    'A',
    'A links the action (capping screen homework) to the outcome (sleep quality) with a specific evidence-based mechanism (evening screen exposure delays sleep onset). B is opinion rather than evidence. C is about marking convenience, not sleep. D addresses digital familiarity, which is not the outcome in the proposition. A is strongest.',
    261,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; recent studies have linked more than 60 minutes of evening screen use in children to falling asleep over 45 minutes later on average, so capping screen homework at 30 minutes directly reduces this evening exposure.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; many parents already believe their children sleep better with less screen time.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; teachers would find it harder to mark work handed in on paper.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; reducing digital homework would slow children''s familiarity with computers.', NULL, 4, NULL
  );

