  -- [267] Community Festival Workshops
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '22146428-aff8-44b1-bbba-becc549f3d89',
    'Community Festival Workshops',
    'venn_diagram'::dm_question_type,
    'The diagram shows 140 workshops offered at a community festival. Each letter marks a different region.

Which letter represents a workshop that is both outdoor and free entry, but is neither hands-on nor held in the afternoon?',
    NULL,
    '{"diagramLayout":"auto","sets":[{"id":"set1","label":"Outdoor","shape":"square"},{"id":"set2","label":"Afternoon","shape":"hexagon"},{"id":"set3","label":"Hands-on","shape":"diamond"},{"id":"set4","label":"Free entry","shape":"isosceles_triangle"}],"regions":{"set1_only":"P","set2_only":"Q","set3_only":"R","set4_only":"S","set1_set2":"T","set2_set3":"U","set3_set4":"V","set1_set4":"W","outside":"X"}}'::jsonb,
    'C',
    'The workshop must be inside Outdoor and Free entry, and outside Hands-on and Afternoon. Letter T is Outdoor-and-Afternoon — includes Afternoon, excluded. Letter U is Afternoon-and-Hands-on — includes two excluded categories. Letter V is Hands-on-and-Free-entry — includes Hands-on, excluded. Letter W is Outdoor-and-Free-entry, sitting outside both Afternoon and Hands-on — this matches. Answer: Letter W.',
    267,
    'normal',
    '{"canvas":{"width":300,"height":400},"shapes":[{"id":"set1","label":"Outdoor","kind":"polygon","points":[[32.191192645837546,25.144606450045146],[236.6861230926396,35.08072627178177],[226.750003270903,239.57565671858384],[22.255072824100907,229.63953689684723]]},{"id":"set2","label":"Afternoon","kind":"polygon","points":[[196.52978058872054,102.56658696676243],[284.79069498719446,149.81826342753408],[288,249.88029568824197],[202.94839061433163,302.6906514881783],[114.68747621585777,255.43897502740666],[111.47817120305221,155.3769427666987]]},{"id":"set3","label":"Hands-on","kind":"polygon","points":[[129.24609760992297,170.9388201912975],[231.42888463769896,272.6726065221789],[129.69509830681756,374.8553935499549],[27.51231127904157,273.1216072190735]]},{"id":"set4","label":"Free entry","kind":"polygon","points":[[54.34985896595214,98.51989589851686],[11.999999999999968,309.163468231055],[116.10872332895345,304.3112168817927]]}],"labels":[{"region":"set1_only","text":"P","x":111.4423564633912,"y":87.13576772399132,"fontSize":16},{"region":"set2_only","text":"Q","x":257.33573330542487,"y":232.34279428201788,"fontSize":16},{"region":"set3_only","text":"R","x":147.921560513634,"y":310.3444404859122,"fontSize":16},{"region":"set4_only","text":"S","x":29.01313787936685,"y":294.21181433549935,"fontSize":23},{"region":"set1_set2","text":"T","x":184.97254731818373,"y":162.827249054732,"fontSize":16},{"region":"set2_set3","text":"U","x":185.0315851384055,"y":263.62618193398987,"fontSize":16},{"region":"set3_set4","text":"V","x":73.19803534991829,"y":272.88959020976216,"fontSize":16},{"region":"set1_set4","text":"W","x":59.34552161625122,"y":204.56731974356342,"fontSize":16},{"region":"outside","text":"X","x":284.15,"y":381,"fontSize":14}],"ambiguity":{"hasDuplicates":false,"allIdentical":false}}'::jsonb
