  -- [271] Glucose Meters
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '0c380260-3c33-4adf-9f30-c0d2fbdbbff9',
    'Glucose Meters',
    'probabilistic'::dm_question_type,
    'A hospital is evaluating two glucose meters. Meter X gives the correct reading in 90 out of 100 tests of known samples. Meter Y gives the correct reading in 80 out of 100 tests of known samples. When each meter re-tests the same sample 40 times in succession, Meter X returns the same reading 32 times and Meter Y returns the same reading 38 times.

Which statement best compares the two meters?',
    NULL,
    NULL,
    'A',
    'Accuracy is how often a reading is correct. Meter X = 90/100 = 90%, Meter Y = 80/100 = 80% — X is more accurate. Precision is how consistently repeated readings agree. Meter X = 32/40 = 80%, Meter Y = 38/40 = 95% — Y is more precise. So X is more accurate but Y is more precise.',
    271,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Meter X is more accurate but Meter Y is more precise.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Meter Y is more accurate but Meter X is more precise.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Meter X is both more accurate and more precise.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Meter Y is both more accurate and more precise.', NULL, 4, NULL
  );

