  -- [273] Three-Day Rain Forecast
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '5e896827-f16a-48ba-a224-e85983afca67',
    'Three-Day Rain Forecast',
    'probabilistic'::dm_question_type,
    'A weather forecaster states that the probability of rain on each of three consecutive days is independently 0.4.

What is the probability that it rains on at least one of the three days?',
    NULL,
    NULL,
    'B',
    'P(no rain on a single day) = 1 − 0.4 = 0.6. P(no rain on all three days) = 0.6 × 0.6 × 0.6 = 0.216. P(at least one day of rain) = 1 − 0.216 = 0.784 = 78.4%.',
    273,
    'hard',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
