  -- [276] Modern Language Enrolments
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'd7b89c9a-5d55-49d2-b72f-6949eef8090c',
    'Modern Language Enrolments',
    'venn_diagram'::dm_question_type,
    'A sixth form has 80 students enrolled on modern language courses. 40 study French, 29 study German, and 28 study Spanish. 12 students study both French and German. 10 students study both German and Spanish. No student studies both French and Spanish. 5 students study none of these three languages.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'A',
    'Two freebies: 5 students study none of the three languages, and no student studies both French and Spanish — so the French and Spanish shapes must not overlap. Scan — C shows 7 outside, not 5 — eliminate C. The stem says 12 study French and German; B shows 10 in that overlap — eliminate B. D shows 14 there — eliminate D. A shows 12 in the French-and-German overlap, 10 in the German-and-Spanish overlap, no French-and-Spanish overlap, and 5 outside. Answer: A.',
    276,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

