  -- [277] Passing at Least One Exam
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'ec49815f-587f-4d5c-abec-4a0f3e1f33cc',
    'Passing at Least One Exam',
    'probabilistic'::dm_question_type,
    'The probability that a student passes the maths exam is 0.7. The probability that they pass the English exam is 0.8. The two events are independent.

What is the probability that the student passes at least one of the two exams?',
    NULL,
    NULL,
    'C',
    'Use the complement. P(fail maths) = 0.3, P(fail English) = 0.2. P(fail both) = 0.3 × 0.2 = 0.06. P(pass at least one) = 1 − 0.06 = 0.94.',
    277,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

