  -- [287] Charity Lottery Tickets
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '9b9f6e8f-5cb6-44df-a833-a383907d4633',
    'Charity Lottery Tickets',
    'probabilistic'::dm_question_type,
    'A small charity lottery sells 600 tickets numbered 1 to 600. One winning ticket is drawn at random. The prize is awarded to any ticket whose number is divisible by exactly one of 4 or 5 (but not both).

What is the probability that the drawn ticket wins the prize?',
    NULL,
    NULL,
    'A',
    'Numbers from 1 to 600 divisible by 4: 600 / 4 = 150. Divisible by 5: 600 / 5 = 120. Divisible by both 4 and 5 (i.e. by 20): 600 / 20 = 30. Divisible by exactly one of 4 or 5 = (150 − 30) + (120 − 30) = 120 + 90 = 210. Probability = 210 / 600 = 7/20.',
    287,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', '7/20', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', '2/5', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', '1/2', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', '1/20', NULL, 4, NULL
  );

  -- [288] Weighing Scales Comparison
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '1f2b0f81-53a7-433f-85bb-54b032b870a6',
    'Weighing Scales Comparison',
    'probabilistic'::dm_question_type,
    'Two weighing scales are tested. Scale 1 gives the correct weight in 88 out of 100 trials; when used 50 times on the same object, it returns the same reading 47 times. Scale 2 gives the correct weight in 94 out of 100 trials; when used 50 times on the same object, it returns the same reading 42 times.

Accuracy is how often a scale gives the correct reading; precision is how consistently it gives the same reading on repeated use. Which statement best compares the two scales?',
    NULL,
    NULL,
    'C',
    'Scale 1: accuracy 88/100 = 88 per cent; precision 47/50 = 94 per cent. Scale 2: accuracy 94/100 = 94 per cent; precision 42/50 = 84 per cent. So Scale 2 is more accurate but Scale 1 is more precise.',
    288,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Scale 1 is more accurate but Scale 2 is more precise.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Scale 2 is both more accurate and more precise.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'Scale 2 is more accurate but Scale 1 is more precise.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'Scale 1 is both more accurate and more precise.', NULL, 4, NULL
  );

