  -- [293] Menu Calorie Labelling
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    'c8d5d5ae-caec-4fcd-87cd-61e04c2c2a69',
    'Menu Calorie Labelling',
    'recognising_assumptions'::dm_question_type,
    'Should restaurants be required to display calorie information on menus to help customers make healthier choices?',
    NULL,
    NULL,
    'A',
    'A links the action (calorie labelling) to the outcome (healthier choices) with cross-country review evidence that average calorie intake per meal fell where labelling was mandatory. B is values-based with no evidence on healthier choices. C critiques the measure rather than the proposition — the limits of calories as a metric don''t show labelling fails to influence choices. D uses vague ''many'' and doesn''t address whether those who do read labels make healthier choices.',
    293,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'A', 'Yes; a 2023 review of menu calorie labelling across 12 countries found average calorie intake per meal fell by 32 kcal where labelling was mandatory.', NULL, 1, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'B', 'Yes; transparency is a core value of modern hospitality.', NULL, 2, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'C', 'No; calorie counts alone don''t capture the full nutritional quality of a meal.', NULL, 3, NULL
  );
  INSERT INTO decision_making_question_options
    (question_id, label, option_text, option_data, order_index, venn_geometry)
  VALUES (
    v_id, 'D', 'No; many customers ignore calorie labels entirely.', NULL, 4, NULL
  );

