  -- [299] Remote Work Wellness Study
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '6f5d1efd-a7b8-4da6-a4e2-fa96d8d7f147',
    'Remote Work Wellness Study',
    'interpreting_info'::dm_question_type,
    'A recent study of office workers reported that those who worked from home at least two days a week had lower self-reported stress than those who came to the office every day. The authors proposed that the reduced commute time explained the difference. Critics noted that the remote-working group was older on average and more likely to have private home offices, both of which may independently reduce stress. The study did not measure productivity or long-term health.',
    NULL,
    NULL,
    '[object Object]',
    NULL,
    299,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Commuting less causes a reduction in self-reported stress.', 'No', 1
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Remote workers in the study reported lower stress than daily office workers.', 'Yes', 2
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Working from home improves long-term health.', 'No', 3
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'The remote-working group in the study was on average older than the office-every-day group.', 'Yes', 4
  );
  INSERT INTO decision_making_question_statements
    (question_id, statement_text, correct_answer, order_index)
  VALUES (
    v_id, 'Older workers are more likely to work from home.', 'No', 5
  );

  -- [300] Import Warehouse
  INSERT INTO decision_making_questions
    (id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty, venn_geometry)
  VALUES (
    '78c85923-0a07-4c1d-aea5-d3154578b1a0',
    'Import Warehouse',
    'venn_diagram'::dm_question_type,
    'A warehouse receives 132 consignments in a month. 55 are imported, 48 are perishable, and 40 require cold storage. 18 are imported and perishable, 14 are imported and requiring cold storage, and 22 are perishable and requiring cold storage. 8 fall into all three categories. 35 do not fall into any of these three categories.

Which of the following diagrams best represents the data?',
    NULL,
    NULL,
    'A',
    'Two freebies: 8 consignments are in all three categories and 35 fall outside all three. Scan — C shows 12 in the centre, stem says 8 — eliminate C. D shows 40 outside, stem says 35 — eliminate D. That leaves A and B. The stem says 18 are imported and perishable, 8 of those are also cold storage, so imported-and-perishable only = 18 − 8 = 10. A shows 10 ✓. B shows 14 — eliminate B. Answer: A.',
    300,
    'normal',
    NULL
  ) RETURNING id INTO v_id;

